quests[58045] = { id = 58045, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seuchen sind dicker als Wasser", description = "Kommt näher, mein Lehrling... Ich habe eine Mission von dringlicher Wichtigkeit für Euch!\n\nKürzlich ist ein Totenbeschwörer zu unserem Haus gekommen, den Lichmarkgräfin Sin'dane geschickt hatte! Er hat so freundlich gewirkt und war stets bereit, bei den instabilsten Schöpfungen meiner Herrin zu helfen.\n\nAber ich habe dazugelernt. Wie er herumgeschlichen ist und in unseren vertraulichsten Experimenten herumgestochert hat...\n\nEr wollte unsere Schleime stehlen! Ich weiß es genau!\n\nIhr solltet ihn scharf verwarnen. Stellt sicher, dass unseren Freunden kein Leid zustößt!", sourceObjective = "Tötet Korrim den Gerissenen.", completion = "Unsere Schleime werden sicher sein, mein teurer Lehrling!", sourceObjectiveStatus = "unverified-source-field" }
quests[58060] = { id = 58060, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Nachtmarkt", description = "<Dracho gibt Euch ein Zeichen, leise zu sein.>\n\nIch brauche Hilfe und ich verspreche, gut dafür zu zahlen.\n\nEs gibt Ruinen am Rande des Fluchwalds. Diese Ruinen sind der Marktplatz für einige Mittler, die mich aber nicht dorthinlassen. Sagen wir einfach, meine Waren entsprechen nicht ihren hohen Echtheitsstandards.\n\nIhr aber seid <ein Schlundgänger/eine Schlundgängerin>! Bringt ihnen dieses Paket im Austausch für ein paar Surbeeren aus dem Ardenwald.\n\nErwähnt aber nicht, dass ich Euch geschickt habe.", sourceObjective = "Bringt das hastig eingepackte Paket zu Taru'ca auf dem Nachtmarkt in Revendreth.\n\nBereitgestellter Gegenstand:", completion = "Ah, Dornbuschrosen! Wunderbar.\n\nGeht noch nicht. Wir müssen reden.", sourceObjectiveStatus = "unverified-source-field" }
quests[58062] = { id = 58062, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein ganz besonderer Gast", description = "Hört zu. Ihr macht dieses Geschäft offensichtlich für Dracho.\n\nIch glaube, Ta'xera, unser Boss hier, würde gern Eure Talente in Anspruch nehmen und Euch ein lohnendes Geschäft vorschlagen.\n\nSie wohnt in dem Anwesen oben auf dem Hügel. Lasst sie besser nicht warten.", sourceObjective = "Sprecht mit Ta'xera auf dem Nachtmarkt.", completion = "Ich habe gehofft, dass Ihr früher oder später herkommt, Schlundgänger.\n\nDracho ist nicht mehr unser Partner. Normalerweise würden wir Euch wie ihn bestrafen, weil Ihr unsere Regeln unterwandern wolltet. Da Ihr aber ein spezieller Fall seid... ändert das einiges.\n\nIch habe Euch ein Geschäft vorzuschlagen.\n\nIhr bringt die interessanten Dinge direkt zu mir. Keine Mittelsmänner. Keine Tricks.\n\nWir entschädigen Euch mit Bezahlung und Waren, wenn es angebracht ist. Schlagt Ihr ein?", sourceObjectiveStatus = "unverified-source-field" }
quests[58068] = { id = 58068, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "... Sogar die lächerlichste Bitte!", description = "Euch gefällt der Wettstreit, was? Vielleicht möchtet Ihr mehr sein als nur ein Zuschauer?\n\nIch werde Euch eine kleine Aufgabe geben... Das wird nicht nur mir weiterhelfen, sondern Euch auch die Gelegenheit verschaffen, einige der herausragenden Wettstreiter hier kennenzulernen.\n\nWie Ihr sehen könnt, haben unsere drei verbliebenen Häuser Champions entsandt, die am Wettstreit der Eroberung teilnehmen. Sprecht mit ihnen und helft ihnen bei dem, was sie brauchen.", sourceObjective = "Kümmert Euch um die Bedürfnisse der Promenadenchampions.", progress = "Was jetzt?", completion = "Ohne Eure Hilfe wären wir verloren. Wahrhaftig.", sourceObjectiveStatus = "unverified-source-field" }
quests[58069] = { id = 58069, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dienst: Die Venthyrtagebücher", description = "Dieser Gegenstand wird die Mittler sicher interessieren.\n\nIhr solltet ihn gemäß der Abmachung mit dem Nachtmarkt direkt zu Ta'xera bringen.\n\nMan wird Euch dafür gebührend entlohnen.", sourceObjective = "Bringt die Venthyrtagebücher zu Ta'xera auf dem Nachtmarkt in Revendreth.\n\nBereitgestellter Gegenstand:", completion = "<Euer Angebot interessiert Ta'xera sichtlich.>\n\nWas mag wohl in diesen Seiten verborgen sein?\n\nSieht nach persönlichen Tagebucheinträgen aus. Sehr interessant. Es gibt hier sogar einen von der Anklägerin selbst!\n\nEs wird mir ein Vergnügen sein, es zu durchstöbern.", sourceObjectiveStatus = "unverified-source-field" }
quests[58070] = { id = 58070, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dienst: Klinge des Seelenjägers", description = "Dieser Gegenstand wird die Mittler sicher interessieren.\n\nIhr solltet ihn gemäß der Abmachung mit dem Nachtmarkt direkt zu Ta'xera bringen.\n\nMan wird Euch dafür gebührend entlohnen.", sourceObjective = "Bringt die Seelenjägerklinge zu Ta'xera auf dem Nachtmarkt in Revendreth.\n\nBereitgestellter Gegenstand:", completion = "Was bringt Ihr mir heute?\n\nAh, ich sehe schon, die Klinge eines Seelenjägers. Die hat sicher einen hohen Wert für alle, die mehr über ihre Duelltechniken erfahren möchten.\n\nIch danke Euch, {name}. Meine Kontakte werden sehr erfreut sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[58071] = { id = 58071, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dienst: Phiole Gräberschlamm", description = "Dieser Gegenstand wird die Mittler sicher interessieren.\n\nIhr solltet ihn gemäß der Abmachung mit dem Nachtmarkt direkt zu Ta'xera bringen.\n\nMan wird Euch dafür gebührend entlohnen.", sourceObjective = "Bringt die Phiole Gräberschlamm zu Ta'xera auf dem Nachtmarkt in Revendreth.\n\nBereitgestellter Gegenstand:", completion = "Was ist das für ein furchtbarer Gestank?!\n\n<Ihr zeigt Ta'xera die Phiole.>\n\nSieh an. Der Gestank mag zwar widerlich sein, aber der Inhalt der Phiole ist makellos. Der urzeitliche Schleim, aus dem die Gräber gemacht werden.\n\nIch zahle Euch das Doppelte, was Ihr sonst an Angeboten erhalten habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[58072] = { id = 58072, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dienst: Versteinertes Steinscheusal", description = "Dieser Gegenstand wird die Mittler sicher interessieren.\n\nIhr solltet ihn gemäß der Abmachung mit dem Nachtmarkt direkt zu Ta'xera bringen.\n\nMan wird Euch dafür gebührend entlohnen.", sourceObjective = "Bringt das versteinerte Steinscheusal zu Ta'xera auf dem Nachtmarkt in Revendreth.\n\nBereitgestellter Gegenstand:", completion = "Ist es das, was ich denke?\n\n<Ta'xera untersucht das Steinscheusal genau.>\n\nIn perfektem Zustand! Ich kann kaum erwarten, jedes Detail zu untersuchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[58073] = { id = 58073, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dienst: Porträt von Graf Denathrius", description = "Dieser Gegenstand wird die Mittler sicher interessieren.\n\nIhr solltet ihn gemäß der Abmachung mit dem Nachtmarkt direkt zu Ta'xera bringen.\n\nMan wird Euch dafür gebührend entlohnen.", sourceObjective = "Bringt das Porträt von Graf Denathrius zu Ta'xera auf dem Nachtmarkt in Revendreth.\n\nBereitgestellter Gegenstand:", completion = "Faszinierend. Man sieht wirklich jedes Detail.\n\nEin wunderbarer Fund, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[58074] = { id = 58074, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dienst: Seelenregister", description = "Dieser Gegenstand wird die Mittler sicher interessieren.\n\nIhr solltet ihn gemäß der Abmachung mit dem Nachtmarkt direkt zu Ta'xera bringen.\n\nMan wird Euch dafür gebührend entlohnen.", sourceObjective = "Bringt das Seelenregister zu Ta'xera auf dem Nachtmarkt in Revendreth.\n\nBereitgestellter Gegenstand:", completion = "Das ist eine lange Liste an Namen, die Ihr da habt. Das wird meinen Studien sicher nutzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[58075] = { id = 58075, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dienst: Gräberwerkzeugsatz", description = "Dieser Gegenstand wird die Mittler sicher interessieren.\n\nIhr solltet ihn gemäß der Abmachung mit dem Nachtmarkt direkt zu Ta'xera bringen.\n\nMan wird Euch dafür gebührend entlohnen.", sourceObjective = "Bringt den Gräberwerkzeugsatz zu Ta'xera auf dem Nachtmarkt in Revendreth.\n\nBereitgestellter Gegenstand:", completion = "Hmm, was haben wir hier? Aha, das sprichwörtliche Handwerkszeug.\n\nIch kann das zwar nicht gebrauchen, aber ich habe Abnehmer, die sich für Infrastruktur interessieren. Sie hätten sicher großes Interesse an dieser Sammlung.", sourceObjectiveStatus = "unverified-source-field" }
quests[58077] = { id = 58077, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dienst: Perfektionierter Handspiegel", description = "Dieser Gegenstand wird die Mittler sicher interessieren.\n\nIhr solltet ihn gemäß der Abmachung mit dem Nachtmarkt direkt zu Ta'xera bringen.\n\nMan wird Euch dafür gebührend entlohnen.", sourceObjective = "Bringt den perfektionierten Handspiegel zu Ta'xera auf dem Nachtmarkt in Revendreth.\n\nBereitgestellter Gegenstand:", completion = "Wirklich edel gefertigt.\n\nDas kann nur eine Arbeit von Laurent sein. Damit kann man Personen absolut unauffällig durch ganz Revendreth transportieren.\n\nDas wird uns gute Dienste leisten.", sourceObjectiveStatus = "unverified-source-field" }
quests[58078] = { id = 58078, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dienst: Flasche Redelavwein", description = "Dieser Gegenstand wird die Mittler sicher interessieren.\n\nIhr solltet ihn gemäß der Abmachung mit dem Nachtmarkt direkt zu Ta'xera bringen.\n\nMan wird Euch dafür gebührend entlohnen.", sourceObjective = "Bringt die Flasche Redelavwein zu Ta'xera auf dem Nachtmarkt in Revendreth.\n\nBereitgestellter Gegenstand:", completion = "Wie dekadent! Redelavwein!\n\nIch bin hin- und hergerissen, die Flasche in meine eigene Sammlung aufzunehmen... oder sie woanders gegen wertvolle Artefakte einzutauschen.\n\nHier, nehmt Eure Bezahlung.", sourceObjectiveStatus = "unverified-source-field" }
quests[58079] = { id = 58079, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dienst: Makelloser Fleddermauszahn", description = "Dieser Gegenstand wird die Mittler sicher interessieren.\n\nIhr solltet ihn gemäß der Abmachung mit dem Nachtmarkt direkt zu Ta'xera bringen.\n\nMan wird Euch dafür gebührend entlohnen.", sourceObjective = "Bringt den makellosen Fleddermauszahn zu Ta'xera auf dem Nachtmarkt in Revendreth.\n\nBereitgestellter Gegenstand:", completion = "Was bringt Ihr mir? Ah, einen intakten Fleddermauszahn.\n\nZiemlich selten, wenn man bedenkt, wie bissig diese Tiere sind. Ich danke Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[58080] = { id = 58080, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dienst: Glitzernde Primulahalskette", description = "Dieser Gegenstand wird die Mittler sicher interessieren.\n\nIhr solltet ihn gemäß der Abmachung mit dem Nachtmarkt direkt zu Ta'xera bringen.\n\nMan wird Euch dafür gebührend entlohnen.", sourceObjective = "Bringt die glitzernde Primulahalskette zu Ta'xera auf dem Nachtmarkt in Revendreth.\n\nBereitgestellter Gegenstand:", completion = "Oh, wie wunderschön. Sehr interessant.\n\n<Ta'xera inspiziert die Halskette näher.>\n\nWoher hatten sie nur dieses Material? Das habe ich ewig nicht zu Gesicht bekommen. Wir können so viel davon lernen.", sourceObjectiveStatus = "unverified-source-field" }
quests[58081] = { id = 58081, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dienst: Liebe und Terror", description = "Dieser Gegenstand wird die Mittler sicher interessieren.\n\nIhr solltet ihn gemäß der Abmachung mit dem Nachtmarkt direkt zu Ta'xera bringen.\n\nMan wird Euch dafür gebührend entlohnen.", sourceObjective = "Bringt Liebe und Terror zu Ta'xera auf dem Nachtmarkt in Revendreth.\n\nBereitgestellter Gegenstand:", completion = "Gedichte? Von einem Venthyr?!\n\nDas ist wirklich überraschend. Ich kann es kaum erwarten, die Schreibstile genauer zu analysieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[58084] = { id = 58084, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seelenfesseln" }
quests[58086] = { id = 58086, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Meister der Lügen", description = "Ein weiteres Mal in den Rachen des Todes höchstpersönlich, das Schwert in der Hand und mit der Vergessenheit im Reinen. Wir werden uns ihm gemeinsam stellen und ihn besiegen.\n\nSorgt dafür, dass Ihr auf andauernde Überfälle vorbereitet seid. Denn sobald wir uns gezeigt haben, gibt es kein Zurück mehr.\n\nRichtet den Brennspiegel auf die Tore von Schloss Nathria, wenn Ihr bereit seid. Lasst uns grimmig und geschwind auf unsere brennenden Gegner niederfahren.", sourceObjective = "Besiegt Graf Denathrius.", completion = "Was hat er getan?", sourceObjectiveStatus = "unverified-source-field" }
quests[58087] = { id = 58087, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Quelle zerstören", description = "Gezeitenruferin Nezara hat hier das Sagen. Wenn wir sie ausschalten, werden sich die restlichen Naga zerstreuen, aber es wird nicht leicht sein, an sie heranzukommen. Sie wird durch eine magische Barriere geschützt, die aus Energiezellen in der Nähe gespeist wird.\n\nWenn wir die Quelle zerstören können, können wir Nezara vernichten.", sourceObjective = "Zerstört 3 Energiezellen der Nazeshi in den Schreckensperlenuntiefen.", completion = "Gezeitenruferin Nezara kann sich jetzt nicht mehr hinter ihrer Barriere verstecken!", sourceObjectiveStatus = "unverified-source-field" }
quests[58088] = { id = 58088, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufgetankt", description = "Ich habe mir eine Aufgabe ausgedacht, die zu Euren \"Talenten\" passt.\n\nHabt Ihr vom Haus der Seuchen gehört? Sie stellen Gifte und Tränke her. Ihnen ist großes Unglück widerfahren. Wirklich eine Schande.\n\nUnd hier liegt das Problem: Ich habe die Schöpfungen der Seuchenerfinder lange Zeit benutzt, um meine Leistung in der Arena zu verbessern. Ohne einen ihrer Tränke empfinde ich Kämpfe als unnötig anstrengend.\n\nDie Mittler haben solche Tränke, aber sie \"können mein Gesicht nicht leiden\". Könntet Ihr so einen Trank für mich erwerben?", sourceObjective = "Findet jemanden auf der Herausfordererpromenade, der Stärkungstränke hat.", completion = "Ich weiß, dass Kämpi Minoire Euch geschickt hat. Sie stärkt sich immer, um den Kampf zu gewinnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[58090] = { id = 58090, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nebenwirkungen", description = "Dass Kämpi Minoire Stärkungen verwendet, hat unvorhersehbare Auswirkungen auf die Wetten. Das ist ungesund... für unsere Profite!\n\nGegen eine geringe Gebühr wird Euch Au'larrynar eine \"spezielle\" Stärkung verkaufen, der Minoire nicht widerstehen kann: einen Trank, der den Konsumenten zum ultimativen Kämpfer macht... und ihm obendrein eine Lektion in Bescheidenheit erteilt.\n\nIch freue mich schon auf Minoires nächsten Kampf in der Arena!", sourceObjective = "Bringt den Trank zu Kämpi Minoire.", progress = "Das ist eine äußerst unerwartete Entwicklung.", completion = "Kämpi Minoire wird ihren Platz im Wettbewerb aufgeben müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[58092] = { id = 58092, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hallen der Sühne: Eure Absolution", description = "Die Verderbtheit außerhalb dieser Hallen ist nur ein leises Echo der wahren Schrecken, die unter der Führung des Obersten Kämmerers in den Hallen der Sühne begangen werden.\n\nWenn Ihr diese Verderbnis wirklich eindämmen wollt, müsst Ihr den Betrüger entthronen, den Ihr hier eingesetzt habt.\n\nBüßt für Euren eigenen Fehler. Tötet den Obersten Kämmerer, sodass wir an diesem Ort bleibende Ordnung wiederherstellen können.", sourceObjective = "Tötet den Obersten Kämmerer in den Hallen der Sühne.", completion = "Ein großer Schritt auf unserem Weg, um die Ehre dieser Hallen wiederherzustellen... aber nicht der letzte.\n\nIch werde die Anklägerin sofort unterrichten.", sourceObjectiveStatus = "unverified-source-field" }
quests[58093] = { id = 58093, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unsere vergessene Bestimmung", description = "Ihr seid nicht mein Feind, <Schlundgänger/Schlundgängerin>.\n\nDer Oberste Kämmerer und seine abscheulichen Anhänger haben diese Hallen mit ihrer Entstellung der Rituale entwürdigt. Sie haben für ihre jämmerlichen Verspottungen der Macht Seelen misshandelt und ihr Potential zerstört.\n\nDie Anklägerin hätte das niemals erlaubt. Gerüchten zufolge seid Ihr immer noch mit ihr in Kontakt. Falls dem so ist, informiert sie bitte über die Lage hier.\n\nSie wird diesen verkommenen Hunden Einhalt gebieten.", sourceObjective = "Sucht die Anklägerin in der Gruft der Absolution auf.", completion = "Ich bin bereits dabei, die Untaten des Obersten Kämmerers rückgängig zu machen.\n\nJa, Ihr dürft mir helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[58095] = { id = 58095, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Theater der Schmerzen: Hilfe Gesucht", description = "Oh, nein... Der Lichchampion hat sich aus dem Wettbewerb zurückgezogen.\n\nTja... Es scheint so, als wäre ein Platz freigeworden! Möchte jemand an ihrer statt teilnehmen?\n\nUm vielleicht die Siegeschancen für das eigene Haus zu verbessern?\n\nKeiner?\n\nOh, {name}! Wie schön, dass Ihr Euch freiwillig meldet. Das ist der beste Weg, um Erfahrung zu sammeln. Einfach rein ins kalte Wasser!\n\nUnd nicht vergessen: Es können nicht alle gewinnen.", sourceObjective = "Begebt Euch in den Dungeon des Theaters der Schmerzen und besiegt die Champions dort.", completion = "Eine spektakuläre Vorstellung, Schlundgänger.", sourceObjectiveStatus = "unverified-source-field" }
quests[58096] = { id = 58096, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorräte von den Rajani", description = "Die Rajani wissen all die Hilfe zu schätzen, die Ihr uns zukommen lassen habt.\n\nBitte, nehmt diese Vorräte als Zeichen unserer Dankbarkeit und als Versprechen, dass es noch mehr davon gibt, wenn Ihr uns weiterhin helft.", sourceObjective = "Sprecht mit Zhang Ku im Tal der Ewigen Blüten, um Eure Belohnung zu erhalten.", completion = "Die Rajani stellen sich an der Seite Ra-dens gegen die Streitkräfte von N'Zoth.\n\nWir werden uns bemühen, Euch auf jede erdenkliche Weise unter die Arme zu greifen. Nehmt fürs Erste diese Vorräte als Unterstützung für die bevorstehenden Kämpfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[58097] = { id = 58097, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorräte vom Abkommen von Uldum", description = "Das Abkommen von Uldum weiß all die Hilfe zu schätzen, die Ihr uns zukommen lassen habt.\n\nBitte, nehmt diese Vorräte als Zeichen unserer Dankbarkeit und als Versprechen, dass es noch mehr davon gibt, wenn Ihr uns weiterhin helft.", sourceObjective = "Sprecht mit Versorgerin Qorra in Uldum über Eure Belohnung.", completion = "Das Abkommen stellt sich dieser Bedrohung entgegen. Ganz Azeroth steht für Eure heldenhaften Bemühungen in Eurer Schuld.\n\nIch danke Euch, Champion!", sourceObjectiveStatus = "unverified-source-field" }
quests[58103] = { id = 58103, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rudel oder Einheit", description = "Ich hoffe, dass die Arbeit mit meinem Phalynx Eure Meinung geändert hat, {name}.\n\nTreffen wir uns mit Nemea. Dort könnt Ihr Euch entscheiden, wessen Lebensweise überlegen ist und welcher Ihr lieber folgen würdet.", sourceObjective = "Trefft Euch mit Pelodis und Nemea und entscheidet Euch für eine Seite.", completion = "Es ist vollbracht.", sourceObjectiveStatus = "unverified-source-field" }
quests[58104] = { id = 58104, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zeigen, nicht erzählen", description = "Als neuer Champion des Hofes müsst Ihr den restlichen Nachtfae gebührend vorgestellt werden. Wir brauchen etwas Großes. Mutiges. Einprägsames. Etwas, das zeigt, wer Ihr seid und wo Ihr herkommt. Etwas mit... Flair.\n\nNormalerweise braucht man Ewigkeiten, um eine großartige Präsentation vorzubereiten. Aber dafür haben wir keine Zeit! Wir werden improvisieren müssen.\n\n<Mondbeere zwinkert.>\n\nHaltet Zwiesprache mit mir, damit ich von Euren größten Taten erfahre. Ich stelle dann sicher, dass es eine unvergessliche Vorstellung wird!", sourceObjective = "Haltet Zwiesprache mit Lady Mondbeere.", completion = "Sehr gut! Ihr seid hier! Wir haben keine Zeit für eine Probe, aber das sollte kein großes Problem sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[58122] = { id = 58122, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Für die Horde", description = "Was für ein Abenteuer, {class}!\n\nEs gibt so viel zu erkunden... so viel zu entdecken. Wir leben in aufregenden Zeiten!\n\nWir werden unseren Verbündeten in der Horde zeigen, wie wertvoll es sein kann, ein paar schlaue Vulpera dabeizuhaben.\n\nBitte trefft Euch mit dem Botschafter in der Botschaft von Orgrimmar.\n\nWir sehen uns dort, {name}!", sourceObjective = "Trefft Euch mit Botschafter Schwarzwacht in der Botschaft von Orgrimmar.", completion = "Seid Ihr neu hier? Ich soll Euch begrüßen.\n\n<Schwarzwacht stößt einen verärgerten Seufzer aus.>", sourceObjectiveStatus = "unverified-source-field" }
quests[58124] = { id = 58124, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fremder in einem fremden Land", description = "Hallo, ich bin Botschafter Schwarzwacht.\n\nEs ist mir eine Ehre, Euch in Orgrimmar willkommen zu heißen, {race}.\n\n<Er lächelt gekünstelt.>\n\nNun, da sich ein Leben voller Abenteuer vor Euch auftut, seid versichert, dass... ähm...\n\nWisst Ihr was? Ich habe diese Begrüßung heute den ganzen Tag immer wieder abgespult. Mir reicht's.\n\nSprecht mit Chromie auf dem Stundenglas. Und dann sprecht mit Eurem Abgesandten. Kusch!", sourceObjective = "Sprecht mit Chromie.", progress = "Diese Stadt ist riesig!", completion = "So viele Möglichkeiten für Euch!\n\nUnd mit Euch meine ich uns. Ich wette, es gibt ein paar faszinierende Kuriositäten zu finden...\n\nSeid vorsichtig dort draußen!", sourceObjectiveStatus = "unverified-source-field" }
quests[58127] = { id = 58127, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sündenstein eines Inquisitors", progress = "Mit meinen Archiven sollte es nicht allzu schwierig sein, den Sündenstein eines Inquisitors zu finden und wiederherzustellen.", completion = "Ihr seid ein starker Schlundgänger. Für Euch sollte es kein Problem sein, einen Inquisitor zu besiegen.\n\nGute Jagd." }
quests[58128] = { id = 58128, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sündenstein eines Hochinquisitors", progress = "Trotz meiner Archive könnte es schwierig werden, den Sündenstein eines Hochinquisitors zu finden und wiederherzustellen.", completion = "Hochinquisitoren sind mächtige Gegner. Stellt Euch ihnen besser nur in einer Gruppe und nicht allein.\n\nGute Jagd." }
quests[58129] = { id = 58129, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sündenstein eines Großinquisitors", progress = "Die Großinquisitoren halten ihre Geheimnisse unglaublich sicher unter Verschluss. Wir werden außergewöhnliche Ressourcen aufwenden müssen, um einen ihrer Sündensteine zu finden und wiederherzustellen.", completion = "Die Großinquisitoren Nicu und Aurica sind die stärksten Venthyr in diesen Hallen, Schlundgänger.\n\nStellt Euch ihnen nicht allein. Ihr braucht dafür Gefährten. Eine Menge Gefährten." }
quests[58144] = { id = 58144, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geschunden und verschrammt" }
quests[58146] = { id = 58146, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Für die Allianz", description = "Als Hochtüftler und Anführer der Gnome sowie der Mechagnome bin ich stolz, Euch in der Allianz willkommen zu heißen!\n\nJenseits der Mauern von Mechagon erwartet Euch eine Welt voller Abenteuer.\n\nWenn Ihr bereit seid, betretet den Teleporter. Botschafter Moorgard erwartet Eure Ankunft in der Botschaft von Sturmwind.\n\nEs werden Euch viele denkbare Wege der Weiterentwicklung offenstehen.\n\nTrefft eine kluge Wahl, verbessert Euch und denkt daran, Eure Daten zu teilen.", sourceObjective = "Trefft Euch mit Botschafter Moorgard in der Botschaft von Sturmwind.", completion = "Ah, da seid Ihr ja, {name}! Wir haben Euch betrach– äh, erwartet!", sourceObjectiveStatus = "unverified-source-field" }
quests[58147] = { id = 58147, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fremder in einem fremden Land", description = "Willkommen in Sturmwind, {class}. Ich lade Euch ein, unsere prächtige Stadt zu erkunden. Hm, Ihr seht aus wie jemand, dem das Nachtleben zusagt. Wir haben viele beliebte Tavernen und eine pulsierende Musikszene!\n\nAber das kann warten. Ein Bronzedrache wollte Euch sprechen. Sie sitzt unter dem Baum in der Nähe, ausgerechnet auf einem Stundenglas!\n\nUnd danach erwartet Euch ein Abgesandter der Mechagnome, der Euch in der Stadt willkommen heißen will. Klingt, als hättet Ihr einen langen Tag vor Euch!\n\nIch wünsche einen angenehmen Aufenthalt, {name}!", sourceObjective = "Findet Chromie in Sturmwind.", progress = "Und? Entspricht Sturmwind Euren Erwartungen?", completion = "Ihr werdet ein ausgezeichneter Repräsentant für das Wesen der Mechagnome sein.\n\nUnd immer schön glänzen da draußen.", sourceObjectiveStatus = "unverified-source-field" }
quests[58151] = { id = 58151, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Diener von N'Zoth", description = "Der heulende Wind, der uns umgibt, wird eines Tages vielleicht übertönt, verborgen unter diesem ständig lauter werdenden, dunklen und doch so vertrauten Geflüster.\n\nMan muss etwas unternehmen.\n\nTaucht in die Finsternis ein, {name}, und bringt den Gegner zur Strecke.", sourceObjective = "Besiegt 20 Diener von N'Zoth in der Vision.", progress = "Der Wind umfängt uns, tröstend, beruhigend... doch darunter lauert eine große, ständig präsente Finsternis.", completion = "Euer Werk wird nicht unbemerkt bleiben. Dessen bin ich mir sicher.", sourceObjectiveStatus = "unverified-source-field" }
quests[58155] = { id = 58155, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Hand in der Dunkelheit", description = "Stellt Euch vor, in einer Welt gefangen zu ein, von deren Existenz Ihr nichts wusstet... in einer Realität, die selbst Ihr nicht kanntet.\n\nGedanken, Ängste und finsteres Verlangen vernebeln im Zusammenspiel mit unwiderstehlicher Versuchung Euren Verstand.\n\nViele gingen an die Finsternis verloren, weil sie dieser Versuchung nicht widerstehen konnten, aber nicht alle.\n\nGebt Euer Bestes, um die zu schützen, die gegen die Finsternis ankämpfen. Wir dürfen nicht zulassen, dass sie fallen.", sourceObjective = "Rettet 8 Seelen aus der Vision.", progress = "Es ist das Beste, nicht lange in der Finsternis zu verweilen.", completion = "Das vernichtende Geflüster lauert. Bleibt wachsam, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[58156] = { id = 58156, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Finsternis niederschlagen", description = "Die Finsternis dehnt sich aus. Der Kreislauf setzt sich fort.\n\nTut, was Ihr könnt, um N'Zoths Anstrengungen Einhalt zu gebieten. Wenn wir uns nicht gegen die Verderbnis stellen, finden wir uns womöglich eines Tages in der Finsternis ertrinkend wieder.", sourceObjective = "Schlagt N'Zoths Verderbnis innerhalb der Vision zurück.", progress = "Wir beide wissen, was getan werden muss.", completion = "Eure Hingabe, sich gegen die Verderbnis zu stemmen, ist von unschätzbarem Wert, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[58157] = { id = 58157, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hals und Beinbruch", description = "Die Vorstellung geht gleich los! Ist... dieser Aufzug Euer Ernst? Na ja, das wird wohl durchgehen.\n\nFür Eure große Vorstellung werden wir als erstes Schauspiel Eure jüngsten Siege und Heldentaten auf Azzinoth... ähm, Azeroth aufführen. Dort kommt Ihr doch her, oder?\n\nDie Theatertruppe Sternenlicht hat sich freundlicherweise dazu bereit erklärt, uns bei dieser Produktion zu helfen, und zudem haben wir einige Überraschungsgäste einladen können!\n\nMacht Euch um das Skript keine Sorgen. Immerhin handelt es sich um Eure Geschichte!\n\nVersucht nur, nicht zu viel Blut auf der Bühne zu vergießen. Das geht so schlecht wieder weg.", sourceObjective = "Führt die Dritte Invasion der Legion in Azeroth auf.", progress = "Nun, das war kein... totaler Reinfall.", completion = "Nicht übel! Nicht überragend, aber nicht übel. Schnell jetzt, wir müssen die Bühne für den nächsten Akt vorbereiten!", sourceObjectiveStatus = "unverified-source-field" }
quests[58158] = { id = 58158, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Vierte Sieg, äh, Krieg", description = "Es ist Zeit für den nächsten Teil Eurer theatralischen Vorstellung: das große Drama von Azereth!\n\nAzeroth. Genau. Diese Welten klingen doch alle gleich.\n\nHelft beim Bühnenaufbau und kommt dann zurück. Ihr müsst zuerst in ein paar andere Rollen schlüpfen, bevor Ihr wieder Euch selbst spielt.\n\nLos jetzt, es gibt viel zu präsentieren!", sourceObjective = "Baut das Bühnenbild auf und helft beim Nachspielen der Ereignisse nach dem Fall der Legion.", progress = "Los, los! Das Publikum wartet!", completion = "Ich kann wirklich sagen, dass ich so eine Leistung noch nie erlebt habe.\n\nUnd jetzt... zu unserem großen Finale! Eine Schlacht um Eure Welt, bei der der Hof sicher aufhorchen und uns aufmerksam folgen wird!", sourceObjectiveStatus = "unverified-source-field" }
quests[58159] = { id = 58159, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meine Motivation", description = "Und jetzt zu unserem Finale! Eine mitreißende Demonstration der jüngsten Herausforderungen in Azathoth!\n\n<Federleicht schaut auf seine Notizen.>\n\nAzeroth. Egal. Es gibt einen künstlichen Gott, eine mächtige magische Eisprinzessin, eine berüchtigte Königin und eine unsägliche Monstrosität unglaublichen Schreckens! Wer kann einem guten Drama mit einer Prise existenziellen Grauens schon widerstehen?\n\nJetzt spielt Ihr wieder Euch selbst, also macht einfach das, was Helden eben so tun!", sourceObjective = "Spielt den letzten Akt!", progress = "Nun, das war aufregend!", completion = "Eine ordentliche Leistung! \n\nIch glaube, jetzt kennt sich jeder ein bisschen besser mit Eurer Welt und der Rolle, die Ihr in ihr gespielt habt, aus.\n\nDas nächste Mal werden wir das Bühnenbild etwas besser... vorbereiten. Aber fürs Erste...\n\n<Sie nickt Ysera zu.>\n\nIch glaube, Eure Freundin möchte reden. Macht nicht zu lange. Es folgt noch die finale Einführungszeremonie im Herz des Waldes.", sourceObjectiveStatus = "unverified-source-field" }
quests[58160] = { id = 58160, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Für Königin und Hain!", description = "Eine beeindruckende Vorstellung... in vielerlei Hinsicht.\n\nIn meiner Abwesenheit ist so viel in Azeroth geschehen. Doch einen Traum habe ich auf der Bühne vermisst.\n\nIch habe von Tyrande geträumt, von Finsternis verschlungen, von Zorn korrumpiert und von Rachedurst getrieben. Ich wurde Zeugin eines verbotenen Rituals, dem Aufstieg eines neuen Nachtkriegers und einer Jagd, die nur tragisch enden kann. Das muss doch auch real sein.\n\n<Ysera schüttelt den Kopf.>\n\nDie Winterkönigin erwartet Euch im Herz des Waldes. Wir sollten lieber aufbrechen.", sourceObjective = "Reist mit Ysera zum Herzbaum und tretet dem Pakt bei.", completion = "Eure Taten werden selbst durch den Schleier hindurch spürbar sein. Helft dem Wald, dann besteht auch Hoffnung für alle sterblichen Welten.", sourceObjectiveStatus = "unverified-source-field" }
quests[58161] = { id = 58161, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Wald verschwunden", description = "Habt Ihr einen Moment Zeit, <mein Freund/meine Liebe>?\n\nVor Kurzem hat ein Sylvar namens Partik unseren Hain um Hilfe ersucht. Er hat gesagt, sein Dorf würde von den Gorm angegriffen und liefe Gefahr, auseinanderzubrechen. Ich habe ihm erzählt, dass wir zwar keine Soldaten entbehren können, aber seine Leute bei uns Zuflucht finden.\n\nJetzt ist seine Abreise allerdings schon eine Weile her und ich habe seitdem keine Nachrichten aus diesem Gebiet erhalten.\n\nKönntet Ihr die Sache für mich untersuchen? Er kam aus dem Nordosten.", sourceObjective = "Findet Partik.", completion = "Nein, nein... Was geschieht hier?", sourceObjectiveStatus = "unverified-source-field" }
quests[58162] = { id = 58162, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geheimnisvolle Masken", description = "Das Dorf, meine Freunde, fort. Sie sind nicht mehr.\n\nIch bin vom Hain in der Nähe zurückgekommen und habe sie... so vorgefunden. Sogar Lavrash, mein bester Freund! Er ist auf mich los, mit nichts als Gewalt in seinem Herzen.\n\nSie haben jetzt alle diese Masken auf und sind nicht mehr sie selbst.\n\nErlöst sie bitte von diesem Schicksal. Bringt mir ihre Masken, dann können wir dieses Mysterium vielleicht auflösen.", sourceObjective = "Sammelt 15 ausdruckslose Masken.", progress = "So viele sind gefallen. Ich dachte nicht, dass ich so lange weggewesen wäre...", completion = "Diese Masken müssen ein Geheimnis bergen, das mit der Besessenheit zu tun hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[58163] = { id = 58163, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine verzweifelte Lösung", description = "<Ihr entdeckt ein kunstvoll gefertigtes und recht abgenutztes Tagebuch.\n\nBeim Durchblättern der Seiten wird Euch klar, dass es einer bedeutenden Person dieser Gruppe von Nachtfae gehört haben muss. Die letzten Seiten wurden aus dem Buch herausgerissen.\n\nWenn sich die fehlenden Seiten finden ließen, könnte es Partik vielleicht gelingen, herauszufinden, was hier vorgefallen ist.>", sourceObjective = "Findet die fehlenden Tagebuchseiten.", progress = "Was habt Ihr denn da?", completion = "<Partik liest sich eilig die letzten Seiten durch und erbleicht.>", sourceObjectiveStatus = "unverified-source-field" }
quests[58164] = { id = 58164, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Persönlichkeitskult", description = "Einige meiner Leute sind noch am Leben! Wir müssen sie retten!\n\nDie Gefangenen sind in Käfigen auf dem Bergkamm verteilt und warten darauf, dass sie das gleiche schlimme Schicksal ereilt.\n\nBitte befreit sie. Wir können nicht zulassen, dass ihnen das Gleiche widerfährt wie Lavrash!", sourceObjective = "Rettet 8 gefangene Nachtfae.", completion = "So wenige... Aber jeder ist ein weiterer Freund, der uns gegen diesen Wahnsinn beistehen kann!", sourceObjectiveStatus = "unverified-source-field" }
quests[58165] = { id = 58165, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wurzelschnitt", description = "Es ist so, wie ich befürchtet habe. Das gesamte Dorf wurde verwandelt, genau wie Lavrash.\n\nLewor muss die anderen Ältesten verwandelt haben, so schnell er nur konnte. Sie alle verfügen über besondere Stärken. Die tapfere Fiona, die kluge Bitterfliege...\n\nIch kann es kaum ertragen, aber sie müssen vernichtet werden. Zum Wohle des Ardenwalds... Tötet unsere vormaligen Anführer, bevor sie den Rest des Landes infizieren können!", sourceObjective = "Tötet Bitterfliege, Fiona Kahldorn und Wildwinder Lewor.", progress = "Wenn sie gefallen sind, welche Hoffnung bleibt uns dann noch?", completion = "<Partik schluckt und erbleicht.>\n\nDas waren also alle? Gut.", sourceObjectiveStatus = "unverified-source-field" }
quests[58166] = { id = 58166, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unbekannte Angreifer", description = "Das muss der Stein sein, den er gefunden hat. Das Zeichen ist mir unbekannt.\n\nIhr solltet das zu den Dromanen gleich hier in der Nähe bringen. Sie sind weise und besitzen umfassendes Wissen über die Wälder und die Reiche jenseits davon. Sie werden wissen, was zu tun ist.", sourceObjective = "Bringt den seltsamen Runenstein zu Dromanin Tashmur in Tirna Vaal.\n\nBereitgestellter Gegenstand:", completion = "Warum seid Ihr so aufgebracht?", sourceObjectiveStatus = "unverified-source-field" }
quests[58167] = { id = 58167, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorbeugende Maßnahmen", description = "Wellen der Finsternis setzen ihre Angriffe an den Ufern unserer Welt fort. Ich fürchte, die Gewässer zu unseren Füßen werden bald über uns zusammenschlagen. Vielleicht ist es Zeit für eine andere Herangehensweise.\n\nMacht Euch auf den Weg in das entstellte Reich und sucht nach ihren dunklen Portalen. Wenn wir ihr Vorrücken verlangsamen können, würde uns das vielleicht die Zeit verschaffen, eine entscheidende Schwäche bei ihnen aufzudecken.", sourceObjective = "Zerstört 3 Leerenportale innerhalb der Vision.", completion = "Eine kurze Atempause. Hoffen wir, dass sie ein Weilchen anhält.", sourceObjectiveStatus = "unverified-source-field" }
quests[58168] = { id = 58168, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Finsteres Starren der Realität", description = "Ihre Blick ruhen auf uns, {name}. Sie beobachten jede Bewegung aus den Schatten. Es ist kein Wunder, dass die Ergebnisse unsere Bemühungen bisher... zu wünschen übrig ließen.\n\nDer Fehler liegt keineswegs bei uns. Wir hätten schon vor langer Zeit den Verdacht hegen sollen, dass dies der Fall ist.\n\nWenn wir unsere Anstrengungen mit konkreten Erwartungen fortsetzen wollen, müssen wir unentdeckt bleiben.\n\nUnser alter Freund hat ein Elixier angeboten, das dabei hilft, unsere Feinde zum Vorschein zu bringen. Es mag ein paar... unbekannte Nebenwirkungen geben, aber wer es trinkt, erhält wahre Sicht in der Finsternis.", sourceObjective = "Besiegt 6 Dunkelblickbeobachter innerhalb der Vision.", progress = "Seht Ihr die Dinge jetzt klarer?", completion = "Haltet die Augen offen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[58174] = { id = 58174, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mehr kann ein Aspirant nicht tun", description = "Ich denke, wir sind einer Meinung, dass eine derartige Antwort... wie eine hohle Phrase klingt.\n\nIch für meinen Teil vertraue darauf, dass wir alles getan haben, was wir konnten. Wir alle. Ich weiß nicht, was als Nächstes geschieht, aber vielleicht wird sich der Weg offenbaren. In der Zwischenzeit werden Pelagos und ich für eine kurze Atempause zur Aspirantenrast zurückkehren.\n\nWir treffen Euch dann dort. Aber es gibt keinen besonderen Grund zur Eile.", sourceObjective = "Kehrt zur Aspirantenrast zurück.", completion = "<Kleia lächelt Euch freundlich an.>\n\nHeißt das, Ihr habt die Absicht, zu bleiben?", sourceObjectiveStatus = "unverified-source-field" }
quests[58175] = { id = 58175, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Ewige Schmiede", description = "Der Oberste Schmied hat die schwere Aufgabe übernommen, unser neues Emblem des Aufstiegs zu erbauen.\n\nDafür braucht er mehr als nur gewöhnliche Materialien oder Werkzeuge. Er braucht Phaestus, Genese der Äonen, den Hammer der Ersten Schmiedin. Er befindet sich im Schrein der Ersten Schmiedin in der Ewigen Schmiede.\n\nDie Verschmähten haben diese Schmiede eingenommen, um ihre eigene riesige Armee von Zenturionen zu erschaffen. Trefft Euch mit Mikanikos an der Schmiede, schlagt die Verschmähten in die Flucht und sichert Phaestus für uns.", sourceObjective = "Trefft Euch mit Mikanikos an der Ewigen Schmiede.", completion = "{name}! Unfassbar, was die Verschmähten meiner Schmiede angetan haben, oder?\n\nWir müssen Phaestus finden und sie aufhalten!", sourceObjectiveStatus = "unverified-source-field" }
quests[58176] = { id = 58176, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Provost und Provost gesellt sich gern", description = "Ihr! <Schlundgänger/Schlundgängerin>!\n\nSehr geschäftig war die Schmiede. Viele Hilfsschmiede bei der Arbeit!\n\nDann kamen Verschmähte! Einige haben ihnen gehorcht, sich auf ihre Seite geschlagen.\n\nAber nicht alle! Ja, rettet Hilfsschmiede, damit sie helfen. Arbeit zu erledigen!", sourceObjective = "Befreit 5 gefangene Hilfsschmiede.", progress = "Ich wollte retten, bin aber keine Heldin. Kann nur versuchen, das Chaos zu organisieren.", completion = "Ihr habt es geschafft! Viele Hilfsschmiede kehren heute zurück. Vielleicht kommt der Rest auch eines Tages wieder?\n\nWir helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[58177] = { id = 58177, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Veredeltes Ego", description = "Ich werde nach Phaestus suchen. Für Euch habe ich eine andere Aufgabe!\n\nDie Verschmähten haben mit meiner Schmiede ihre Armee von Zenturionen erschaffen. Ihre furchtbaren Absichten verderben das Metall, mit dem wir arbeiten!\n\nZerstört ihre Zenturionen, nehmt die Teile und schmelzt sie in der Schmiede ein, um das Metall zu läutern. Kommt anschließend zu mir zurück.\n\nFür meinen Plan brauche ich jede Menge Metall.", sourceObjective = "Besorgt 8 geläutertes Metall, indem Ihr besudelte Zenturiokomponenten von Zenturioeinheiten sammelt und sie dann in der Ewigen Schmiede einschmelzt.", progress = "Hier lagern meine Ressourcen. Die Verschmähten haben mich bestohlen! Das werden sie mir büßen.", completion = "Das Metall brauchen wir für viele Dinge. Für das Emblem und für meinen Goliath!", sourceObjectiveStatus = "unverified-source-field" }
quests[58178] = { id = 58178, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Partner für die Ewigkeit", description = "Noch eins zu tun, bevor wir in die Feste zurückkehren.\n\nDie Verschmähten und ihre Armee von Zenturionen besiegen!\n\nUnd dabei hilft uns dieser Goliath. Mein absolutes Meisterwerk!\n\nIch brauche noch ein paar helfende Hände. Eure werden reichen.", sourceObjective = "Helft Mikanikos, sein Meisterwerk zu vollenden.", completion = "Ein Partner, der meine innere Stärke wie kein Zweiter verkörpert.\n\nWahrlich ein Meisterstück von einem Zenturio!", sourceObjectiveStatus = "unverified-source-field" }
quests[58179] = { id = 58179, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Instrumente der Perfektion", description = "Mikanikos ist kein einfacher Provost. Er ist weise! Talentiert! Der Schlaueste von uns allen!\n\nAuch ziemlich eigen!\n\nOhne sein Werkzeug kann er nicht arbeiten. Die Verschmähten haben es überall in der Schmiede verstreut!\n\nIhr müsst Emblem neuerschaffen? Dann holt sein Werkzeug!", sourceObjective = "Sammelt Mikanikos' Seelenstahlklammern, seinen funkelnden Strömungskugelkern und sein Gnadenblütenräuchergefäß ein.", progress = "So kann ich nicht arbeiten.", completion = "Sika hat Euch geschickt, mein Werkzeug zu holen?\n\nSie weiß, was ich brauche, um arbeiten zu können.", sourceObjectiveStatus = "unverified-source-field" }
quests[58180] = { id = 58180, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Phaestus, Genesis der Äonen", description = "Laut Sika sind die Verschmähten überall. Sie haben nicht nur die Produktion übernommen, sondern auch die Anhöhe!\n\nSie kontrollieren ihre Armeen von den Klippen aus und halten ihre Anführer ständig auf dem Laufenden.\n\nSie haben unseren Schrein zu Ehren der Ersten Schmiedin geplündert und ihren Hammer gestohlen. Meinen Hammer!\n\nBesiegt ihren Kommandanten und holt Phaestus zurück. Geht! Sofort!", sourceObjective = "Holt Phaestus, Genesis der Äonen, von Aufseher Atticus zurück.", progress = "Ohne Phaestus können wir nicht an diesem Emblem arbeiten.", completion = "Phaestus ist zurück! Was für ein Tag.\n\nVielen Dank. Seit Äonen reichen wir diesen Hammer an unsere Nachfolger weiter! Sein Platz ist hier, in meinen meisterlichen Händen.", sourceObjectiveStatus = "unverified-source-field" }
quests[58181] = { id = 58181, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit dem Fundament fängt alles an", description = "Das Emblem ist fast fertig.\n\nDie Ehre des Feinschliffs überlasse ich Euch.\n\nIhr habt viel geschafft. Hier, bitte nehmt Phaestus und führt den letzten Schlag aus!", sourceObjective = "Schmiedet das Emblem des Aufstiegs fertig.", completion = "Perfektion!\n\nEs ist wunderschön, ja? Aber noch nicht fertig. Viel Arbeit lohnt sich am Ende. Ganz bestimmt.", sourceObjectiveStatus = "unverified-source-field" }
quests[58182] = { id = 58182, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Offensive Demontage", description = "Die Verschmähten mobilisieren ihre Armee!\n\nWir können nicht zulassen, dass sie losmarschieren!\n\nStimmt Euch auf Bron ein, teilt Eure Kraft mit ihm.\n\nDann zerstören wir drei diese neue Armee von Zenturionen!", sourceObjective = "Reitet auf Bron, besiegt 30 Soldaten der Verschmähten und zerlegt 2 Kolosse in der Ewigen Schmiede.", completion = "Fantastisch! Bron wird immer stärker dank Eurer Kraft!", sourceObjectiveStatus = "unverified-source-field" }
quests[58183] = { id = 58183, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Herz für Schmiede", description = "Jetzt bauen wir mit Phaestus das neue Emblem.\n\nKommt, wir gehen zurück in die Elysische Feste. Als Sieger!", sourceObjective = "Kehrt zu Polemarch Adrestes in die Elysische Feste zurück.", completion = "Mikanikos ist gerade erst mit seinem neuen Zenturio zurück. Eine ziemlich einzigartige Einheit.\n\nUnd das Phaestus endlich wieder in der Hand eines Kyrianers ruht, ist eine gute Nachricht. Die Archon wird zufrieden sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[58184] = { id = 58184, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Antiquierte Methodik", description = "Ihr habt ein Händchen für die Neuausbildung von Phalynx. Ich glaube, Ihr könntet hier sehr erfolgreich sein.\n\nAber bevor Ihr Euch festlegt, solltet Ihr unbedingt auf der anderen Hügelseite mit meiner Rivalin Nemea sprechen. Sie ist tatsächlich überzeugt, dass ihre unvernünftigen Larions mit freiem Willen bessere Partner abgeben als meine perfekten Phalynx.\n\nIhr müsst Euch das mit eigenen Augen ansehen. Dann seht Ihr, wie viel besser meine Arbeit ist.", sourceObjective = "Sprecht mit Nemea in Nemeas Zuflucht.", completion = "Pelodis hat Euch geschickt, was?\n\nSicher, seine Phalynx befolgen Befehle, aber wo bleibt die Finesse?", sourceObjectiveStatus = "unverified-source-field" }
quests[58185] = { id = 58185, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erfolg ohne Seele", description = "Die Larions scheinen Eure Gesellschaft wirklich zu genießen. Besonders Andira.\n\nIch hoffe, Ihr wisst jetzt, wie erfüllend die verschiedenen Nuancen bei der Arbeit mit Wildtieren sind, die einen freien Willen besitzen.\n\nJetzt müsst Ihr Zeit mit Pelodis weiter unten am Hügel verbringen. Seine Phalynx mögen vielleicht effektiv sein, aber die Arbeit mit ihnen bietet nur oberflächliche Befriedigung.\n\nIch bin sicher, dass Ihr durch die Arbeit mit den Phalynx die Larions noch mehr zu schätzen lernen werdet.", sourceObjective = "Sprecht mit Pelodis am Schmiedefeueraußenposten.", completion = "Ihr seid also als Erstes Nemea begegnet.\n\nSeid beruhigt, dass Ihr hier nicht mit durchgedrehten Tieren arbeiten werdet.", sourceObjectiveStatus = "unverified-source-field" }
quests[58207] = { id = 58207, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Durchdrehen" }
quests[58208] = { id = 58208, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorsicht, Einschlag!", description = "Das Aufwärmen ist abgeschlossen. Ihr und die anderen Rekruten seid ein vielversprechender Haufen, so viel kann ich sagen.\n\nMoment... Was ist das für ein Geräusch? Ich glaube, da kommt etwas Großes auf uns zu!", sourceObjective = "Findet Lady Jaina Prachtmeer im Schiff.", completion = "Dieses Schiff kommt vielleicht nicht bis zur Insel.\n\nHaltet Euch an etwas Robustem fest und bleibt bei Euren Kameraden. Wir schaffen das.", sourceObjectiveStatus = "unverified-source-field" }
quests[58209] = { id = 58209, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Standhalten", description = "Dieser Regen ist hoffentlich kein schlechtes Omen... Dies sollte eigentlich eine einfache Rettungsmission werden.\n\nIch bin heute Euer Sparringspartner. Wir müssen sichergehen, dass Ihr bei der Landung wisst, was zu tun ist.\n\nZeigt, was Ihr draufhabt!", sourceObjective = "Übt mit dem Gefreiten Cole.", progress = "Probleme? Das passiert allen mal. Bleibt einfach ruhig, wählt ein Ziel aus und wendet eine Eurer Fähigkeiten darauf an.\n\nStellt sicher, dass Euer Ziel direkt vor Euch ist. Wir wollen nicht, dass nochmal so etwas passiert wie bei Björn, als er versucht hat, eine Axt über seine Schulter zu schleudern.", completion = "Ihr seid ein fähiger {class}, Rekrut. Ich glaube, Ihr werdet eine Bereicherung für das Hauptrettungsteam darstellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[58211] = { id = 58211, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufgepumpt", description = "Als diese Nekropole zusammenbrach, sind viele ihrer Teile im Flussbett draußen untergegangen. Ich hoffe, dass Ihr den Wiederaufbau tatkräftig unterstützen wollt, denn wir werden diese Teile wieder ausgraben!\n\nNehmt diese Pumpe. Wenn Ihr in dem Schlick Stellen findet, an denen Blasen aufsteigen, könnt Ihr davon ausgehen, dass dort Teile zu finden sind!\n\nAber seid vorsichtig mit dem, was Ihr hochzieht. Einiges davon könnte Widerstand leisten.", sourceObjective = "Sammelt 15 Teile geborgene Ausrüstung, indem Ihr die Schlickpumpe beim blubbernden Schlick verwendet.", progress = "Habt Ihr etwas Nützliches gefunden?", completion = "Bis zu den Knien im Matsch, toll!", sourceObjectiveStatus = "unverified-source-field" }
quests[58214] = { id = 58214, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Notfallbehandlung", description = "Genau zur rechten Zeit, {name}.\n\nKelsey Stahlfunken hat Mitteilungen an die Hauptstädte geschickt und um Hilfe ersucht.\n\nMekkadrills Zustand ist ausgesprochen schlecht und die Zeit drängt.\n\nEilt zum Hafen von Boralus, sie wird dort Ausschau nach Euch halten.", sourceObjective = "Sucht Kelsey Stahlfunken im Hafen von Boralus auf.", completion = "Ihr kommt gerade rechtzeitig.", sourceObjectiveStatus = "unverified-source-field" }
quests[58216] = { id = 58216, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verschlingendes Maul" }
quests[58221] = { id = 58221, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Revanche" }
quests[58229] = { id = 58229, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorbildfunktion", description = "Unser Land wurde von Dienern der Alten Götter verseucht. Sie greifen überall an, sogar in den Köpfen unserer Soldaten.\n\nWir können dem nicht lange standhalten. Wir müssen einen deutlichen Sieg erringen, um die Moral der Soldaten wiederherzustellen.\n\nSucht die größten, schleimigsten, tentakelgesichtigsten Monstrositäten, die Ihr finden könnt, und tötet sie. Das wird meine Männer wieder anspornen.", sourceObjective = "Tötet 3 seltene Diener von N'Zoth in Uldum.", completion = "Eure Siege am heutigen Tag werden meinen Männern noch lange Mut machen.\n\nRamkahen schuldet Euch etwas, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[58230] = { id = 58230, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Augen schließen", description = "In letzter Zeit haben merkwürdige Kräfte meine Visionen gestört. Die ewig wachsamen Blicke dringen durch den Schleier und zersplittern meine Hellsicht.\n\nDie Augen unserer Feinde starren in unsere Seelen und durchbohren unseren Verstand. Wir müssen sie herausreißen, wenn wir den Fluch restlos aus diesem Land vertreiben wollen.", sourceObjective = "Tötet 6 üble Beobachter auf den Feldern von Akhenet in Uldum.", completion = "Ihre Augen sind geschlossen und meine Hellsicht kehrt zurück.\n\nHabt Dank, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[58231] = { id = 58231, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weisheit aus Wahnsinn", description = "In meinen Visionen höre ich... Stimmen...\n\nDie Worte ergeben keinen Sinn, aber mit der Zeit erkenne ich Muster. Ich glaube, diese Stimmen wollen etwas Wichtiges mitteilen, aber ich habe noch kein einziges Wort davon entschlüsselt.\n\nWir müssen mehr über die Quelle erfahren. Bringt mir alle Schriften, die Ihr bei den Kultisten findet, die mit diesen dunklen Kreaturen reisen. Ihre sinnlosen Worte sind vielleicht der Schlüssel zur Botschaft, die hinter diesem Wahnsinn liegt.", sourceObjective = "Sammelt 10 irrsinnige Schriften von Kultisten des Schwarzen Imperiums in Uldum.", progress = "Habt Ihr die Schriften gefunden?", completion = "Wie ich es mir dachte, die Schriftstücke der Kultisten sind komplett zusammenhanglos.\n\nHoffentlich finden wir in diesem Wahnsinn ein Stück Wahrheit.", sourceObjectiveStatus = "unverified-source-field" }
quests[58232] = { id = 58232, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ordnung im Chaos", description = "Es ist schon lange her, seit die Tol'vir sich Streitkräften der Alten Götter entgegengestellt haben. Unser taktisches Wissen über ihre Truppen ist entsprechend beschränkt.\n\nEin Grundsatz des Kampfes wird aber immer seine Gültigkeit haben: Wenn die Befehlshaber ausgeschaltet werden, schwächt das den Gegner mehr, als wenn Fußvolk besiegt wird. \n\nIch habe beobachtet, dass die größeren gesichtslosen Diener in den Streitkräften der Alten Götter als Kommandanten dienen. Bringt sie zum Schweigen, und wir können so vielleicht Chaos und eine andere Art Wahnsinn in ihren eigenen Reihen verbreiten.", sourceObjective = "Tötet 6 gesichtslose Diener von N'Zoth in Uldum.", completion = "Ein entscheidender Schlag gegen ihre Kommandanten sollte uns ein bisschen Zeit verschaffen.\n\nIch danke Euch, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[58233] = { id = 58233, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entstellte Verderber", description = "Die Fleischbestien unter den einfallenden Truppen sind zwar bestenfalls störende Ärgernisse, aber sie besitzen trotzdem eine starke Verbindung zur verderbenden Macht der Alten Götter. \n\nSie verbreiten N'Zoths Verderbnis wie eine Seuche, egal wo sie sind, und verändern das Land selbst langsam, aber sicher nach ihrem Bild.\n\nSie müssen ausgelöscht werden.", sourceObjective = "Tötet 10 Fleischbestien in Uldum.", completion = "Uldum seufzt bei jedem Tod einer der entstellten Manifestationen N'Zoths erleichtert auf.", sourceObjectiveStatus = "unverified-source-field" }
quests[58234] = { id = 58234, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fragwürdige Ressourcenbeschaffung", description = "Meine Hellseherei ist für das Volk von Ramkahen ein wahrer strategischer Vorteil. Allerdings haben meine Visionen aufgrund meiner schlechten Gesundheit in letzter Zeit an Kraft verloren.\n\nIch habe ein Tonikum hergestellt, das vielleicht dabei hilft, den Schaden abzuschwächen, den diese Visionen verursachen. Dafür brauche ich allerdings die kondensierte Essenz der Verderbnis der Alten Götter.\n\nWenn Ihr mir davon einige Proben besorgen könntet, könnte das für unsere Sache von unschätzbarem Wert sein.", sourceObjective = "Sammelt 8 verschmolzene Verderbnis von Schleimen in Uldum.", progress = "Habt Ihr das Reagenz erbeuten können?", completion = "Ihr habt ein paar Proben gesammelt? Wunderbar.\n\nHoffen wir, dass sie den gewünschten Effekt haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[58235] = { id = 58235, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anker des Schwarzen Imperiums", description = "Diese Invasion hat uns ohne Vorwarnung getroffen. Aus dem Nichts sind plötzlich Bauten, die an das Schwarze Imperium erinnern, aufgetaucht und haben unser Land mit Streitkräften der Alten Götter überschwemmt. Wir haben keinen Schimmer, woher oder wie sie hierhergekommen sind.\n\nAllerdings haben wir beobachtet, dass bevor ein solches Bauwerk auftaucht, bösartige Obelisken erscheinen. Wir glauben, dass diese Obelisken als Anker dienen, um mehr Truppen der Alten Götter zu leiten.\n\nWenn wir diese Invasion wirklich aufhalten wollen, müssen wir die Obelisken zerstören.", sourceObjective = "Zerstört 6 Obelisken des Schwarzen Imperiums in Uldum.", completion = "Die Bedrohung ist zwar noch lange nicht ausgeschaltet, aber es tut gut, zu wissen, dass die Verstärkung unserer Feinde nun wirksam langsamer eintrifft. \n\nVielleicht überleben wir gerade lange genug, um diese Schlacht zu Ende zu bringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[58236] = { id = 58236, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Symbolische Zerstörung", description = "Die Kultisten, die dieser dunklen Legion folgen, beschmutzen unser Land mit Symbolen der Tyrannen, denen sie folgen. \n\nIhre verblendeten Anhänger scharen sich um diese Banner und beten sie als unheilige Götzen an.\n\nBrennt sie nieder und säubert unser Land von diesem Schmutz.", sourceObjective = "Zerstört 6 Banner des Schwarzen Imperiums in Uldum.", completion = "Fein. Es wird ein guter Tag sein, wenn diese schändlichen Zeichen unser Land nicht länger verschandeln.", sourceObjectiveStatus = "unverified-source-field" }
quests[58237] = { id = 58237, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Uldum reinigen", description = "Jede Minute, die N'Zoths Truppen länger in Uldum verweilen, sickert seine Verderbnis tiefer in unser Land.\n\nSogar wenn wir es schaffen sollten, seine Diener zu vertreiben, ist der Schaden, den sie Uldum zugefügt haben, vielleicht schon irreversibel.\n\nWir müssen seine Verderbnis in jedem Winkel aufspüren, in dem sie sich einnistet, und sie auslöschen.", sourceObjective = "Zerstört 6 Verderbnistumore in Uldum.", completion = "Ich fühle, wie N'Zoths Verderbnis schwindet.\n\nDas habt Ihr gut gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[58238] = { id = 58238, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verloren und gefoltert", description = "Die Bürger von Ramkahen konnten sich rechtzeitig vor dem Hauptangriff von N'Zoth in Sicherheit bringen.\n\nUnsere Brüder in der Verlorenen Stadt hatten nicht so viel Glück. Wer nicht direkt getötet wurde, wurde gefangen genommen, um von den Dienern N'Zoths gefoltert zu werden.\n\nIch weiß, dass Ihr die Streitkräfte N'Zoths angreifen werdet. Wenn Ihr zudem unsere Verbündeten befreien könnt, wird Ramkahen auf ewig in Eurer Schuld stehen.", sourceObjective = "Befreit 6 Bürger von Ramkahen aus den Folterzellen in der Verlorenen Stadt der Tol'vir in Uldum.", completion = "Unsere Bürger stehen so hoch in Eurer Schuld, wie es kaum wiedergutgemacht werden kann, {name}.\n\nRamkahen dankt Euch für Eure Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[58239] = { id = 58239, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lektionen im Plündern", description = "Die Wüstenwanderer sind schon seit vielen Generationen Räuber, zu Land und zur See. Wir haben uns zwar entscheiden, diese Lebensweise an den Nagel zu hängen und die Chance auf ein friedlicheres Leben zu nutzen, aber wir haben die Lektionen, die wir in unserer Vergangenheit gelernt haben, nicht vergessen.\n\nEine dieser Lektionen ist meiner Meinung nach gerade jetzt sehr passend: Wenn man einem stärkeren Feind gegenübersteht, hilft es meist, seine eigenen Waffen gegen ihn einzusetzen.\n\nFindet ihre verborgenen Truhen und nehmt mit, was Ihr tragen könnt. Ihr findet vielleicht etwas, was diese Schlacht zu unseren Gunsten beeinflussen kann.", sourceObjective = "Plündert 3 Truhen des Schwarzen Imperiums in Uldum.", completion = "Ich hoffe, Ihr habt gefunden, was Ihr gesucht habt.\n\nWir können in diesem Kampf jede erdenkliche Hilfe brauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[58256] = { id = 58256, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verschlingendes Maul" }
quests[58257] = { id = 58257, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verschlingendes Maul" }
quests[58258] = { id = 58258, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verschlingendes Maul" }
quests[58260] = { id = 58260, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Königinnen und zukünftige Könige", description = "Ein Schwarm Markbohrköniginnen hat Eier auf den Ruinen unseres Hauses gelegt. Das könnten wir zu unserem Vorteil nutzen.\n\nEliminiert mit Twigins Hilfe die Königinnen und holt die Larven aus den Eiern.\n\nIch habe etwas mit den Larven vor, mit dem wir unseren Vorteil aus den Markbohrern ziehen können.", sourceObjective = "Tötet 1 Markbohrköniginnen und sammelt 5 Markbohrlarven.", progress = "Schmutzige Arbeit, aber wir brauchen die Larven.", completion = "Und jetzt setzen wir sie sinnvoll ein.", sourceObjectiveStatus = "unverified-source-field" }
quests[58264] = { id = 58264, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufwachen, hoch mit Euch und raus da", description = "Sie brauchen Eure Hilfe!\n\nNoch wurden nicht alle Feen verwandelt. Einige sind Gefangene, aber haben diese Masken auf ihren Gesichtern...\n\nIhr müsst ihnen helfen! Ich bin nicht stark genug, die Masken zu entfernen, aber Ihr seid es sicher! Und Ihr könnt dafür sorgen, dass die Wachen uns nicht erwischen!", sourceObjective = "Helft 8 unterworfenen Feen.", completion = "Ihr habt meine Freunde gerettet!\n\n<Primula schenkt Euch ein kleines Lächeln.>\n\nWir... Wir geben ein gutes Team ab, nicht wahr?", sourceObjectiveStatus = "unverified-source-field" }
quests[58265] = { id = 58265, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blühendes Böses", description = "Irgendetwas ist hier faul, <Reisender/Reisende>. Die Luft im Westen stinkt vor Bösartigkeit.\n\nSchimmergeäst war immer eine friedliche Wegstation auf dem Pfad der Wiedergeburt. Die Feen dort feierten rauschende Feste. Nun ist es still auf ihrer Lichtung.\n\nSpäher berichten von Nachtfae mit merkwürdigen Masken. Ich weiß kaum etwas darüber, nur, dass sie eine Gefahr für uns sind.\n\nSie müssen sterben, dem Ardenwald zuliebe. Tötet alle, die Ihr antrefft.", sourceObjective = "Tötet 15 maskierte Nachtfae in Schimmergeäst.", completion = "Grausame Arbeit, aber notwendig. Mögen sie als nützliche Vasallen des Ardenwalds wiedergeboren werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[58266] = { id = 58266, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abriss", description = "Ich habe das Ritual gesehen. Es ist... schrecklich.\n\nDie Altäre scheinen der Schlüssel zu sein. Hätte ich doch nur mein Pyropulver, dann könnte ich sie in kleine Stücke zerfetzen!\n\n<Primula schweigt einen Moment und atmet dann tief ein.>\n\nWenn Ihr das Pulver holen und mich beschützen könnt, könnten wir diese Altäre in die Luft jagen.\n\nIch habe davon so viel in unseren Behausungen gelagert, wie ich konnte. Ihnen scheint es mittlerweile egal zu sein.\n\nIhr habt zwar keine Flügel, aber etwas Feenstaub sollte für eine kurze Zeit funktionieren.\n\nGehen wir es an, bevor ich meine Meinung ändere!", sourceObjective = "Benutzt Primulas Pyropulver, um 5 Ritualaltäre zu zerstören.", completion = "Geschafft! Alle Altäre sind Geschichte!", sourceObjectiveStatus = "unverified-source-field" }
quests[58267] = { id = 58267, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unter der Maske", description = "Es ist Zeit, das hier zu beenden.\n\nAls ich mich zuerst versteckt hatte, sah ich auf der Plattform im Nordosten einen dunklen Schemen. Das muss wohl ihr Anführer sein.\n\nJetzt, da sie keine Rituale mehr durchführen können, sollten wir sie in die Flucht schlagen können.\n\n<Primula hält für einen Augenblick inne.>\n\nIch... möchte Euch noch danken. Das hätte ich ohne Eure Hilfe nicht hinbekommen. Vertreiben wir jetzt diesen Feind und erobern wir das Dorf zurück!", sourceObjective = "Stellt Euch dem Anführer der besessenen Fae in Schimmergeäst.", completion = "Ich verstehe. Das sind fürchterliche Neuigkeiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[58268] = { id = 58268, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hoch hinaus", description = "General Alver, der Kommandant der Konstrukte, ist ein meisterlicher Taktiker. Ein Frontalangriff gegen ihn ist aussichtslos. Es wird ein Blutbad.\n\nSeine Streitkräfte haben uns umzingelt und die höheren Lagen gesichert. Aus dieser Position kann er ungehindert Tod und Zerstörung auf uns niederprasseln lassen.\n\nWir nehmen ihm den Felskamm, bevor das passieren kann.", sourceObjective = "Zerstört die drei feindlichen Positionen.", completion = "Mit dem eingenommenen Felskamm können wir sicher vorstoßen.", sourceObjectiveStatus = "unverified-source-field" }
quests[58271] = { id = 58271, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ritual der Leerenflamme" }
quests[58272] = { id = 58272, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Worte tragen Macht", description = "Die Rebellen der Steingeborenen haben Anwerbungspamphlete hinterlassen. Wenn Ihr diese für die Venthyr sichern könnt, würde Euch das vielleicht etwas dringend benötigte Gunst eintragen.", sourceObjective = "Sammelt 9 Rebellionshandzettel.", progress = "Die rüden und abscheulichen Dokumente wurden allerdings mit einer eleganten Handschrift gefertigt. Der Prinz hatte schon immer mehr Kunstfertigkeit als Verstand.", completion = "Bah, was für ein Schund. Gebt sie mir und ich werde sie endgültig entsorgen.\n\nHier, für Eure Mühen. Diese Belohnung hilft Euch hoffentlich dabei, den Schmutz dieser Schriften von Euren Fingern zu waschen.", sourceObjectiveStatus = "unverified-source-field" }
quests[58273] = { id = 58273, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Diener von N'Zoth", description = "{class}...\n\nIch habe Euch beobachtet... Ich habe Euren Blutdurst gespürt. \n\nIhr dient aber falschen Propheten... Die Horde ist eine Täuschung... Ich bin ein Gott!\n\nBeweist mir, dass Ihr meines Geschenkes würdig seid... Tötet die, die Euch hintergehen wollen...\n\nTötet... die Horde!", sourceObjective = "Benutzt N'lyeth, Splitter von N'Zoth, um Eure Fraktionszugehörigkeit von der Horde in einen Ergebenen von N'Zoth zu ändern. Tötet dann 10 Spielercharaktere der Horde, ohne zu sterben.", sourceObjectiveStatus = "unverified-source-field" }
quests[58274] = { id = 58274, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Diener von N'Zoth", description = "{class}...\n\nIch habe Euch beobachtet... Ich habe Euren Blutdurst gespürt. \n\nIhr dient aber falschen Propheten... Die Allianz ist eine Täuschung... Ich bin ein Gott!\n\nBeweist mir, dass Ihr meines Geschenkes würdig seid... Tötet die, die Euch hintergehen wollen...\n\nTötet... die Allianz!", sourceObjective = "Benutzt N'lyeth, Splitter von N'Zoth, um Eure Fraktionszugehörigkeit von der Allianz in einen Ergebenen von N'Zoth zu ändern. Tötet dann 10 Spielercharaktere der Allianz, ohne zu sterben.", sourceObjectiveStatus = "unverified-source-field" }
quests[58275] = { id = 58275, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Monströse Beschwörung" }
quests[58276] = { id = 58276, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mar'at in Flammen" }
quests[58277] = { id = 58277, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dunkle Täuscher", description = "Die Alten Götter haben viele gesichtslose Diener in ihren Rängen, aber die schlimmsten Täuscher sind die, die sie K'thir nennen.\n\nSie sehen zwar nicht annähernd so imposant aus wie ihre Brüder, aber die K'thir manipulieren aus den Schatten heraus und entstellen den Geist ihrer Opfer und sogar die Realität selbst.\n\nIhren Machenschaften muss ein Ende gesetzt werden.", sourceObjective = "Tötet 8 K'thirdiener in Uldum.", completion = "Diese Kreaturen dürfen nicht ungehindert in Uldum umherstreifen.\n\nGute Arbeit, Ihr habt sie deutlich dezimiert.", sourceObjectiveStatus = "unverified-source-field" }
quests[58279] = { id = 58279, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kopfgeld des Rüstmeisters", progress = "Um den Feind zu besiegen, braucht Ihr Ausrüstung im Topzustand. Wenn Ihr Euch keine mächtigere Ausrüstung beschaffen konntet, kann ich für Euch welche vom Rüstmeister anfordern.", completion = "Sieg um jeden Preis." }
quests[58281] = { id = 58281, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Uralte Ausrüstung", description = "Der Kampf an mehreren Fronten hat unsere Vorräte dezimiert. Unsere Schmiede können die Rüstungen unserer Soldaten nicht schnell genug reparieren oder ersetzen. In diesem Zustand können wir so vielen Feinden unmöglich gegenübertreten.\n\nDie Rüstung der Amathet ist zwar uralt, aber sie ist titanengeschmiedet und mächtig. Wenn wir Teile davon bergen könnten, wäre das sehr nützlich für unsere Verteidigung.\n\nKönnt Ihr helfen?", sourceObjective = "Sammelt 10 Rüstungsteile der Amathet von gepanzerten Tol'vir der Amathet in Uldum.", progress = "Seid Ihr mit der Rüstung zurückgekommen?", completion = "Ich danke dem Licht, dass Ihr zurückgekehrt seid! Unsere Soldaten brauchen diese Rüstung dringend.\n\nEure Taten werden das Leben vieler Bewohner von Ramkahen sichern, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[58282] = { id = 58282, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aus dem Himmel herab", description = "Die Bogenschützen von Ramkahen sind extrem gut ausgebildet, aber die Bögen der Amathet haben eine höhere Reichweite. Unsere Vorstöße auf ihr Gebiet werden dadurch sehr gefährlich.\n\nIhr seid doch spezialisiert auf den Kampf hinter feindlichen Linien. Wenn Ihr ihre Reihen dezimiert, könnten wir die Gelegenheit nutzen und ihre Linien auch einmal zurücktreiben.\n\nKönnt Ihr uns helfen?", sourceObjective = "Tötet 8 Bogenschützen der Amathet in Uldum.", completion = "Die Pfeile der Amathet verdunkeln unseren Himmel nicht mehr.\n\nWir müssen diese Gelegenheit für einen Gegenschlag nutzen!", sourceObjectiveStatus = "unverified-source-field" }
quests[58283] = { id = 58283, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blinde führen Blinde", description = "Die Sonnenpriester sind ein uralter Orden der Tol'vir, der in allen Stämmen willkommen war. \n\nDiejenigen, die den Amathet folgen, haben unsere Werte allerdings entstellt und als Waffen benutzt, um ihren Kampf gegen Ramkahen zu rechtfertigen. Ihre Soldaten folgen ihnen in blindem Gehorsam.\n\nSie müssen aufgehalten werden.", sourceObjective = "Tötet 8 Priester der Amathet in Uldum.", completion = "Der Tod meiner Brüder erfüllt mich mit Trauer, aber wir müssen die Amathet aufhalten.\n\nIch danke Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[58284] = { id = 58284, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erlasse des Sonnenkönigs", description = "Über den Anführer der Amathet, den Sonnenkönig, ist nur wenig bekannt. Unsere Beobachtungen legen nahe, dass seine engsten Vertrauten Sonnenberührte genannt werden und eine einzigartige Kaste von Zauberern der Solarmagie sind.\n\nIch würde gerne mehr über diesen Sonnenkönig erfahren. Allerdings möchte ich nicht wie die Forscherliga das Leben meiner Forscher für meine Neugier riskieren.\n\nIhr könnt offenbar sehr gut auf Euch selbst aufpassen. Falls Ihr auf Aufzeichnungen über den Sonnenkönig stoßt, würde ich sie gerne an mich nehmen.", sourceObjective = "Sammelt 6 Erlasse des Sonnenkönigs von sonnenberührten Amathet in Uldum.", progress = "Habt Ihr schon etwas Interessantes gefunden?", completion = "Diese Zeichen sind wahrlich faszinierend!\n\nMeine Forscher werden sofort mit deren Entschlüsselung anfangen!", sourceObjectiveStatus = "unverified-source-field" }
quests[58285] = { id = 58285, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausgegrabene Artefakte", description = "Seit die Amathet aus ihren Gräbern gekommen sind, graben sie Titanenrelikte in der Umgebung aus.\n\nIch weiß nicht, was sie mit denen vorhaben. Sie könnten sie auch nur sammeln, damit wir sie nicht bekommen. In jedem Fall bin ich mir sicher, dass die Forscherliga die Relikte gerne studieren würde!\n\nAllerdings kommen wir nicht nahe genug an sie heran, ohne dass die Amathet uns mit ihren Äxten einen Scheitel ziehen wollen. Für Euch ist das ja aber kein Problem, oder?\n\nKönnt Ihr helfen?", sourceObjective = "Sammelt 6 Titanenartefakte in Uldum.", progress = "Hattet Ihr Glück mit den Artefakten?", completion = "Ihr habt es wirklich drauf, oder?\n\nWir könnten mehr verlässliche Leute wie Euch in der Liga brauchen...", sourceObjectiveStatus = "unverified-source-field" }
quests[58286] = { id = 58286, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fern der Heimat", description = "Die Eroberung des östlichen Uldum durch die Amathet kam unerwartet, und wir konnten unsere weiter entfernten Siedlungen nicht rechtzeitig warnen. \n\nZum Glück wurden viele der Tol'vir, die in den eroberten Gebieten lebten, nicht getötet. Allerdings wurden sie unter der erbarmungslosen Peitsche der Amathet versklavt. \n\nWir müssen jede Möglichkeit nutzen, sie zu befreien und nach Hause zurückzubringen.", sourceObjective = "Befreit 6 versklavte Tol'vir in Uldum.", completion = "Viele Brüder unseres Volkes sind dank Euch zurückgekehrt.\n\nIhr habt meinen Dank.", sourceObjectiveStatus = "unverified-source-field" }
quests[58287] = { id = 58287, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein durchschlagender Plan", description = "Berichte meiner Späher erwähnen mehrere Götzen und Monumente, die von den Amathet genutzt werden, um ihre Solarmagie zu kanalisieren.\n\nIch weiß zwar nicht, was genau sie vorhaben, aber wir sollten sie aller möglichen Vorteile berauben. Geht also dorthin und zerstört alles, das auch nur im Entferntesten magisch aussieht.\n\nAber erzählt der Forscherliga nichts davon. Das würde sie mir nie verzeihen.", sourceObjective = "Zerstört 4 Götzen der Amathet und 2 sonnenberührte Obelisken in Uldum.", completion = "Gute Arbeit, {class}.\n\nLangsam aber sicher schwächen wir die Entschlossenheit der Amathet.", sourceObjectiveStatus = "unverified-source-field" }
quests[58288] = { id = 58288, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Erwählten des Sonnenkönigs", description = "Oberflächlich wirken die Amathet zwar unerschütterlich, aber jeder Soldat hat einen Schwachpunkt. Wir müssen ihren Truppen die unmissverständliche Botschaft schicken, dass mit uns nicht zu spaßen ist.\n\nFindet die stärksten Krieger in ihren Rängen und tötet sie vor ihren Augen. \n\nWir zeigen ihnen die wahre Stärke von Uldum!", sourceObjective = "Tötet 3 seltene Gegner der Amathet in Uldum.", completion = "Ein wirkungsvolles Manöver, {class}!\n\nWir finden schon noch einen Weg, die Amathet zu brechen!", sourceObjectiveStatus = "unverified-source-field" }
quests[58289] = { id = 58289, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bewachte Geheimnisse", description = "Nach dem, was wir über die Amathet wissen, müssen sie in ihren Gräbern für Tausende von Jahren eingeschlossen gewesen sein. Stellt Euch nur vor, was wir alles von ihnen erfahren könnten!\n\nNatürlich wäre das viel einfacher, wenn sie nicht versuchen würden, uns zu töten. \n\nWenn Ihr bei Euren Streifzügen auf irgendwelche Truhen mit Relikten der Amathet stoßt, lasst es mich wissen. Ich würde zu gern erfahren, welche Geheimnisse in ihnen schlummern!", sourceObjective = "Plündert 3 Truhen der Amathet in Uldum.", completion = "Faszinierender Fund!\n\nIch kann es kaum erwarten, dass die Situation hier sich so weit beruhigt, dass wir selbst mal einen Blick in diese alten Gräber werfen können!", sourceObjectiveStatus = "unverified-source-field" }
quests[58290] = { id = 58290, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champions der Amathet", description = "Ramkahen verfügt über tapfere und verlässliche Soldaten.\n\nSie können es mühelos mit jedem Fußsoldaten der Amathet aufnehmen. Die Kämpfer der höheren Kasten sind aber einfach zu stark, selbst für unsere mächtigsten Krieger.\n\nFür Euch sollten sie jedoch kein Problem darstellen. Es wäre unschätzbar wertvoll für unsere Verteidigung, wenn Ihr sie ausschalten könntet, während meine Kämpfer ihre Fußsoldaten beschäftigen.", sourceObjective = "Tötet 6 Elitekämpfer der Amathet in Uldum.", completion = "Gute Arbeit, {class}. Meine Soldaten sollten den Rest erledigen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[58291] = { id = 58291, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wüste Wilderer", description = "Die Wüstenwanderer haben unsere Rüstungen aus den Pelzen der Hyänen in der Gegend hergestellt. Seit die Amathet hier aufgetaucht sind, haben ihre Jäger unglücklicherweise unsere üblichen Jagdgebiete überrannt.\n\nWir brauchen diese Pelze und zahlen einen guten Preis dafür. Nehmt sie entweder den Jägern ab oder häutet die Hyänen selbst, wenn Ihr das könnt.", sourceObjective = "Sammelt 6 unverwüstliche Hyänenpelze von Jägern der Amathet oder häutet dafür selbst Hyänen in Uldum.", progress = "Habt Ihr die Pelze mitgebracht?", completion = "Ihr rettet uns damit wahrhaft das Leben, Champion.\n\nHier ist Eure versprochene Belohnung.", sourceObjectiveStatus = "unverified-source-field" }
quests[58297] = { id = 58297, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesichtslosenmaske des Waghalsigen", description = "Der Jäger wollte nie anführen, jedoch suchte er unablässig nach Herausforderungen. Er führte seine Verbündeten mit geschickter Hand und scheute sich nicht, im Nahkampf sein eigenes Leben zu riskieren. Das Können, das er zeigte, machte ihn genau wie meine anderen Diener noch tödlicher. Bringt diese Maske zurück zum Altar des Waghalsigen, um Eure eigene Entschlossenheit im Kampf zu testen, während die Angriffe Eurer Feinde noch tiefere Wunden schlagen.", sourceObjective = "Bringt die Gesichtslosenmaske des Waghalsigen zu dem Altar in einer verstörenden Vision zurück.", progress = "Legt die Gesichtslosenmaske des Waghalsigen auf den Altar.", completion = "Der Pfad des Waghalsigen steht Euch offen, wenn Ihr es wagen wollt.", sourceObjectiveStatus = "unverified-source-field" }
quests[58314] = { id = 58314, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesichtslosenmaske der Verbrannten Brücke", description = "Eine Kriegerin in fremder Umgebung hat keinen festen Stand, insbesondere dann, wenn sie aus ihrer Heimat vertrieben wurde. Die Leere macht diese Unsicherheit zur Realität, bei der ein falscher Schritt in den Abgrund führt oder Eure Seele ausbluten lässt.", sourceObjective = "Bringt die Gesichtslosenmaske der Verbrannten Brücke zu dem Altar in einer verstörenden Vision zurück.", progress = "Legt die Gesichtslosenmaske der Verbrannten Brücke auf den Altar.", completion = "Der tückische Pfad der Verbrannten Brücke steht Euch offen, wenn Ihr es wagen wollt.", sourceObjectiveStatus = "unverified-source-field" }
quests[58316] = { id = 58316, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesichtslosenmaske der Finsteren Vorstellungen", description = "Diese Magier entstellen ihre Magie, um die Welt zu manipulieren und zu erobern. In der Hoffnung auf größere Macht wandeln sie auf den Pfaden des Reichs der Leere. Bei diesen Unterfangen haben die Magier herausgefunden, dass die wahrhaft dunklen und schrecklichen Dinge in den Tiefen der eigenen Vorstellung verborgen liegen.", sourceObjective = "Bringt die Gesichtslosenmaske der Finsteren Vorstellungen zu dem Altar in einer verstörenden Vision zurück.", progress = "Legt die Gesichtslosenmaske der Finsteren Vorstellungen auf den Altar.", completion = "Die Gefahren aus den dunklen Winkeln Eures Verstandes werden sich jetzt manifestieren, wenn Ihr es wagen wollt.", sourceObjectiveStatus = "unverified-source-field" }
quests[58317] = { id = 58317, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesichtslosenmaske des Leidenden", description = "Das Handeln mit Geheimnissen, das Handeln mit Lügen und das Wandeln am Rande der Schatten sind die Fähigkeiten des Spionagemeisters. Seine Leidenschaft und all seine Lieben sind seiner Loyalität zur Krone zum Opfer gefallen. Nichts ist mehr übrig, nichts als der Schmerz. Schmerz ist ein fähiger Lehrer und ein Werkzeug, mit dem sich die Leere genau auskennt. Bringt meine Maske zurück, wenn Ihr es wagen wollt, die verschiedenen Formen des Leides zu ertragen.", sourceObjective = "Bringt die Gesichtslosenmaske des Leidenden zu dem Altar in einer verstörenden Vision zurück.", progress = "Legt die Gesichtslosenmaske des Leidenden auf den Altar.", completion = "Mein Wahnsinn und meine Qual sind wohl noch nicht genug für Euch. Dann setzt Euch in Zukunft gerne noch mehr Leid aus.", sourceObjectiveStatus = "unverified-source-field" }
quests[58318] = { id = 58318, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesichtslosenmaske der Langen Nacht", description = "Das Durchhaltevermögen, das nötig ist, um so weit zu kommen, ist wirklich außerordentlich und die Eigenschaft eines wahrhaft erfahrenen Abenteurers. Die längste Nacht ist jetzt ganz nahe, und mit ihr kommt die ultimative Herausforderung. Diejenigen, die das Kommen des ewigen Zwielichts verhindern wollen, kämpfen einen sinnlosen Kampf. In der längsten Nacht werden sie ewig am Rande des Wahnsinns bleiben.", sourceObjective = "Bringt die Gesichtslosenmaske der Langen Nacht zu dem Altar in einer verstörenden Vision zurück.", progress = "Legt die Gesichtslosenmaske der Langen Nacht auf den Altar.", completion = "Mit einem Schritt in Richtung der längsten Nacht werdet Ihr den Verstand sehen, den Ihr bereits verloren habt. Wollt Ihr den Rest in solch einem nutzlosen Unterfangen auch noch riskieren?", sourceObjectiveStatus = "unverified-source-field" }
quests[58321] = { id = 58321, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ungewöhnlicher Kern", description = "Unsere Späher berichten, dass die Amathet neue Titanenwächter bauen. \n\nWir dachten lange, dass diese Kunst im Sand der Zeit verloren gegangen ist. Anscheinend lagen wir falsch.\n\nIch brauche Euch sicher nicht zu sagen, was für ein Vorteil es wäre, die Hilfe der Wächterkonstrukte bei den Schlachten um Uldum zu auf unserer Seite zu haben. Wir müssen an die Geheimnisse ihrer Konstruktion herankommen!\n\nDie Macht der Titanenwächter liegt in ihrem Kern. Bringt mir einen solchen Kern, damit unsere Konstrukteure seinen Aufbau studieren können.", sourceObjective = "Besorgt einen titanischen Kern von einem Elfenbeinbeobachter in Uldum.", progress = "Konntet Ihr den Kern besorgen?", completion = "Wunderbar! So etwas habe ich noch nie gesehen!\n\nIch schicke das sofort zu meinen Konstrukteuren. Hoffentlich können sie das Wissen, das sich darin verbirgt, entschlüsseln.", sourceObjectiveStatus = "unverified-source-field" }
quests[58325] = { id = 58325, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beobachter Emil", description = "Beobachter Emil ist mein getreuer Aufseher über die Katakomben. Bevor ich in den Schlund geworfen wurde, wurde ihm eine Hälfte des Spiegels anvertraut.\n\nIch habe dafür gesorgt, dass er an den Katakomben der Reue stationiert wird. Aber ich weiß nicht, wo genau er sich in dem weitläufigen Gebiet befindet.\n\nEs gibt einen Wachposten in der Nähe des Eingangs zu den Katakomben. Beginnt Eure Suche dort. Dort gibt es einen Offizier, der uns helfen kann, ich... ich erinnere mich aber nicht mehr, wer genau. Das heißt, vorausgesetzt, er hat dieses ganze Durcheinander überlebt.\n\nIhr müsst Emil sofort finden. Wir haben womöglich nicht viel Zeit.", sourceObjective = "Sucht nach Beobachter Emil in den Katakomben der Reue.", progress = "Ein Freund der Kuratorin?", completion = "Das war nicht der erste Auftragsmörder, mit dem ich mich bislang auseinandersetzen musste. Und es wird nicht der letzte sein.\n\nDie Kuratorin muss Euch geschickt haben. Jemand hat unsere Verbündeten in Archivam gegen uns aufgehetzt...\n\nIch habe die Spiegelscherbe, die sie mir anvertraut hat. Wir müssen uns beeilen.", sourceObjectiveStatus = "unverified-source-field" }
quests[58326] = { id = 58326, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Katakomben durchkämmen", description = "Als die Animadürre begann, versagte allmählich unsere Verteidigung.\n\nUnsere Wachen, die durch den Mangel an Anima geschwächt waren, wurden überwältigt, als die Sündensteine, auf denen dieses Land aufgebaut ist, sich überall um uns herum erhoben. Ganz zu schweigen davon, dass die Manifestationen der Seelen, um die sich niemand mehr kümmern kann, völlig außer Kontrolle sind.\n\nIhr solltet uns doch helfen können, <Sterblicher/Sterbliche>. Bitte, wir können diese Position kaum noch halten... Ich weiß nicht, wie lange das noch gut geht.", sourceObjective = "Tötet 12 Manifestationen und 3 Sündensteinrandalierer in den Katakomben der Reue.", completion = "Ich danke Euch. Könnt Ihr mir einen Gefallen tun und es nicht der Kuratorin sagen? Sie wäre mit den Zuständen hier nicht zufrieden.", sourceObjectiveStatus = "unverified-source-field" }
quests[58327] = { id = 58327, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Häppchen für Steinkopf", description = "<Steinkopf hat sich eine große Sammlung von halbgegessenen Merkwürdigkeiten angelegt.\n\nEr freut sich sicher, wenn Ihr ihm ein paar neue kreative Häppchen zum Probieren bringt.>", sourceObjective = "Sammelt Proben von Häppchen aus dem Glutdistrikt für Steinkopf.", progress = "Bauch knurrig...", completion = "<Steinkopfs Augen leuchten, als er den großen Haufen an halbessbaren Delikatessen sieht, die Ihr ihm gebracht habt.>\n\nIhr guter Freund! Guter Freund kann gehen, wohin er will!", sourceObjectiveStatus = "unverified-source-field" }
quests[58328] = { id = 58328, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "TBD", description = "Felsfuß bestechen" }
quests[58334] = { id = 58334, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nebelhauch in Flammen" }
quests[58337] = { id = 58337, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausbruch", description = "Unsere Verstärkung ist nie angekommen, und so waren wir nicht in der Lage, uns um die Seelen hier zu kümmern. Sie haben damit begonnen, aus ihren Zellen auszubrechen. Viele von ihnen sind noch nicht bereit für den nächsten Schritt im Prozess.\n\nNehmt diese Eisenketten. Ihr könnt sie dazu verwenden, sie unter Kontrolle zu bringen.\n\nSobald Ihr eine Seele gefesselt habt, könnt Ihr sie in einen beliebigen unbeschädigten Käfig zurückbringen.", sourceObjective = "Benutzt die Ketten der Reue bei entlaufenen Gefangenen und bringt sie in einem beliebigen unbeschädigten Katakombenkäfig unter.", completion = "Danke, {name}. Die Seelen sind voller Eitelkeit, Wut und Traurigkeit.\n\nDie Fortsetzung ihres Arrests wird ihnen helfen, sich ihrer Vergangenheit zu stellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[58339] = { id = 58339, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eroberungsbelohnung" }
