quests[58348] = { id = 58348, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eroberungsbelohnung" }
quests[58351] = { id = 58351, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Hügel der Augen", description = "Die anderen Häuser haben noch keinen ausgewachsenen Angriff verübt, aber verwechselt ihre Feigheit nicht mit Inkompetenz.\n\nJeder Taktiker, der sein Gewicht in Maldrazit wert ist, weiß um den Wert von Spionage. Ich vermute, dass die Agenten des Feindes in diesem Moment in unseren Reihen lauern.\n\nNehmt einen meiner Hunde. Er erkennt den Feind am Geruch. Sobald dieses Geschmeiß demaskiert ist, tötet ihr es.", sourceObjective = "Stöbert versteckte Spione mit dem Leichenhund der Auserwählten auf.", completion = "Wenn sie eine Aufdeckung nicht verhindern können, verdienen sie es nicht zu überleben.", sourceObjectiveStatus = "unverified-source-field" }
quests[58352] = { id = 58352, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eroberungsbelohnung", sourceObjective = "Eure Kühnheit auf dem Schlachtfeld ist ohnegleichen.", sourceObjectiveStatus = "unverified-source-field" }
quests[58367] = { id = 58367, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ermächtigter Verwüster" }
quests[58370] = { id = 58370, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ermächtigter Verwüster" }
quests[58372] = { id = 58372, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geht voran", description = "Wir müssen uns jetzt auf den Weg machen. Das wird nicht der letzte Auftragsmörder gewesen sein, dem wir begegnen.\n\nIch kann mit Dunkelheit einen gewissen Schutz bieten, aber denkt daran, dass dieser Zauber nicht unfehlbar ist.\n\nGenug geredet. Wir müssen mit meiner Spiegelscherbe so schnell wie möglich zur Kuratorin gelangen.", sourceObjective = "Begleitet Beobachter Emil aus den Katakomben der Reue hinaus.", completion = "Danke, dass Ihr ihn sicher hergebracht habt, {name}. Ich bin froh, dass er lebt.\n\nDa wir jetzt seine Spiegelscherbe in der Hand halten, fällt uns die bedauerliche Aufgabe zu, auch Mateos Spiegelscherbe zu erlangen.\n\nIch kann nicht glauben, dass er uns verraten hat. Offenbar sind viele Venthyr wieder in ihre sündige Art verfallen...", sourceObjectiveStatus = "unverified-source-field" }
quests[58373] = { id = 58373, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ny'alotha: MUTTERs Führung", description = "Ny'alotha unterliegt nicht den Regeln von Raum und Zeit, und das können wir vielleicht zu unserem Vorteil nutzen.\n\nMUTTER hat eine Theorie, dass wir, wenn es uns gelingt, bestimmte Objekte von den Auserwählten N'Zoths an uns zu bringen, mit diesen den Raum beugen und unsere Reise hierher in die Zukunft beschleunigen können. Obwohl ich bezweifle, dass sie uns diese Gegenstände freiwillig überlassen.", sourceObjective = "Sammelt 4 Titanenkerne von Ra-den, 4 Drachenherzen von Vexiona und 4 prophetische Augen von Il'gynoth in Ny'alotha, der Erwachten Stadt, auf dem Schwierigkeitsgrad 'Normal'.", progress = "Ohne die Gegenstände kann MUTTER keine sichere Reise garantieren.", completion = "Mit diesen Gegenständen kann MUTTER eine sichere Reise zu diesem Bereich garantieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[58374] = { id = 58374, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ny'alotha: MUTTERs Führung", description = "Ny'alotha unterliegt nicht den Regeln von Raum und Zeit, und das können wir vielleicht zu unserem Vorteil nutzen.\n\nMUTTER hat eine Theorie, dass wir, wenn es uns gelingt, bestimmte Objekte von den Auserwählten N'Zoths an uns zu bringen, mit diesen den Raum beugen und unsere Reise hierher in die Zukunft beschleunigen können. Obwohl ich bezweifle, dass sie uns diese Gegenstände freiwillig überlassen.", sourceObjective = "Sammelt 4 Titanenkerne von Ra-den, 4 Drachenherzen von Vexiona und 4 prophetische Augen von Il'gynoth in Ny'alotha, der Erwachten Stadt, auf dem Schwierigkeitsgrad 'Heroisch'.", progress = "Ohne die Gegenstände kann MUTTER keine sichere Reise garantieren.", completion = "Mit diesen Gegenständen kann MUTTER eine sichere Reise zu diesem Bereich garantieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[58375] = { id = 58375, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ny'alotha: MUTTERs Führung", description = "Ny'alotha unterliegt nicht den Regeln von Raum und Zeit, und das können wir vielleicht zu unserem Vorteil nutzen.\n\nMUTTER hat eine Theorie, dass wir, wenn es uns gelingt, bestimmte Objekte von den Auserwählten N'Zoths an uns zu bringen, mit diesen den Raum beugen und unsere Reise hierher in die Zukunft beschleunigen können. Obwohl ich bezweifle, dass sie uns diese Gegenstände freiwillig überlassen.", sourceObjective = "Sammelt 4 Titanenkerne von Ra-den, 4 Drachenherzen von Vexiona und 4 prophetische Augen von Il'gynoth in Ny'alotha, der Erwachten Stadt, auf dem Schwierigkeitsgrad 'Mythisch'.", progress = "Ohne die Gegenstände kann MUTTER keine sichere Reise garantieren.", completion = "Mit diesen Gegenständen kann MUTTER eine sichere Reise zu diesem Bereich garantieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[58376] = { id = 58376, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Konstruktteil: Nekromantisches Öl", description = "<Damit könnte man eine mächtige Monstrosität fertigen. Vielleicht weiß Rathan, wie wir es benutzen können.>", sourceObjective = "Bringt diesen Teil zu Rathan am Metzgerblock.\n\nBereitgestellter Gegenstand:", completion = "Mit dieser Zutat könnte man eine äußerst mächtige Monstrosität fertigen. Ihr solltet sie aufbewahren, bis wir einen Zweck dafür haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[58379] = { id = 58379, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Konstruktteil: Unbezwingbare Haut", description = "<Damit könnte man eine mächtige Monstrosität fertigen. Vielleicht weiß Rathan, wie wir es benutzen können.>", sourceObjective = "Bringt diesen Teil zu Rathan am Metzgerblock.\n\nBereitgestellter Gegenstand:", completion = "Mit dieser Zutat könnte man eine äußerst mächtige Monstrosität fertigen. Ihr solltet sie aufbewahren, bis wir einen Zweck dafür haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[58382] = { id = 58382, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Rettung würdig", sourceObjective = "Befreit Kael'thas Sonnenwanderer in Sündensturz.", completion = "Es wird nicht leicht sein, Kael'thas Sonnenwanderer zu erlösen, und der Ausgang ist keineswegs garantiert.\n\nDennoch müssen wir es versuchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[58383] = { id = 58383, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die vielen Sünden des Kael'thas Sonnenwanderer", description = "Kael'thas Sonnenwanderer stand am Rande der Vernichtung, als wir ihn aus Schloss Nathria gerettet haben.\n\nDenathrius hatte Kael'thas mit unvorstellbaren Mengen von Anima erfüllt. Jeder einzelne Tropfen enthielt die Sünden anderer.\n\nDadurch wurde seine Seele stark, aber instabil und verwirrt, und wurde an den Rand ihrer eigenen Existenz gedrängt.\n\nVertraut mir, wenn ich Euch sage, dass Kael'thas Sonnenwanderer genug eigene Sünden besitzt.\n\nHelft mir dabei, herauszufinden, welche der vielen Sünden, die seiner Seele aufgeladen wurden, tatsächlich seine eigenen Bürden sind.", sourceObjective = "Helft der Anklägerin, die Sünden von Kael'thas Sonnenwanderer zu identifizieren.", completion = "Damit das klar ist: Wir haben Kael'thas Sonnenwanderer keine dieser Sünden erlassen.\n\nVielleicht werden sie ihm nie erlassen. Schlussendlich muss es seine Entscheidung sein, sich zu ändern.\n\nAber wir haben seine Seele stabilisiert. Dadurch hat er immerhin die Gelegenheit, diese Entscheidung selbst zu treffen.", sourceObjectiveStatus = "unverified-source-field" }
quests[58384] = { id = 58384, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurückgelassene Gräber", description = "Als Prinz Renathal aus dem Finsterwallturm floh, musste er viele Leute und Besitztümer zurückzulassen.\n\nDie mächtigen Relikte und Waffen wurden vor langer Zeit ins Versteck des Meisters abtransportiert. Doch die Gräber des Prinzen wurden dazu gezwungen, zu bleiben und stattdessen den verräterischen Lakaien des Meisters zu dienen.\n\nIhr werdet ein willkommener Anblick für sie sein, ein Zeichen, dass der Prinz sie nicht vergessen hat.\n\nWenn sie bereit sind, zu kämpfen, helft ihnen bei der Flucht. Ich sorge dann dafür, dass sie sicher nach Sündensturz gebracht werden.", sourceObjective = "Helft 10 Gräbern bei der Flucht aus dem Finsterwallturm.", completion = "Ich muss zugeben, ich hätte nicht gedacht, dass die Gräber so eifrig für ihre eigene Freiheit kämpfen würden.\n\nIch schätze, der Prinz inspiriert uns alle.", sourceObjectiveStatus = "unverified-source-field" }
quests[58385] = { id = 58385, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Opfern erlernen", description = "In seinem jetzigen Zustand ist Kael'thas weiterhin instabil. Er platzt vor Anima aus allen Nähten.\n\nAußerdem ist er ein arroganter, egoistischer Schwachkopf.\n\nZum Glück kenne ich eine Lektion, mit der man beides angehen kann.\n\nWahre Anführer opfern etwas von sich selbst, um diejenigen in ihrer Obhut zu stärken.\n\nViele Steingeborene, Gargons und sogar das Haustier des Prinzen blieben durch die Mächte des Meisters schlafend in Finsterwall zurück.\n\nBefehlt Kael'thas, Teile der Anima, die in ihm gefangen ist, aufzugeben und damit die schlafenden Steingeborenen wiederzubeleben, damit sie uns helfen.", sourceObjective = "Helft Kael'thas, Vrednic, das Haustier des Prinzen, und andere schlafende Steingeborene im Finsterwallturm zu reanimieren.", completion = "Jetzt ist Kael'thas Sonnenwanderer möglicherweise bereit für das Ritual der Absolution.", sourceObjectiveStatus = "unverified-source-field" }
quests[58386] = { id = 58386, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meine Stärken nutzen", description = "<Kael'thas sieht sich um, um sicherzugehen, dass die Anklägerin außer Hörweite ist.>\n\ndie Anklägerin ist so besessen von meinen negativen Eigenschaften, dass sie meine Stärken gar nicht wahrnimmt!\n\nNoch im Tode bin ich unglaublich mächtig. die Anklägerin hat selbst gesagt, dass Denathrius mich mit Anima erfüllt hat, um mich zu stärken.\n\nLasst uns diese Stärke nutzen, solange ich sie besitze!\n\nDieser Turm gehörte früher dem Prinzen dieses Reichs, nicht wahr? Finden wir die Umstürzlerin, die seinen Thron geraubt hat, und üben wir Vergeltung!\n\nVergeltung wusste ich schon immer am besten zu schätzen.", sourceObjective = "Helft Kael'thas, Thronräuberin Simona zu stellen.", completion = "Ich erwarte nicht, dass Kael'thas sofort zustimmt oder auch nur den Wert von Gnade versteht.\n\nAbsolution ist ein langer, langsamer Prozess. Dies war nur der erste Schritt.", sourceObjectiveStatus = "unverified-source-field" }
quests[58387] = { id = 58387, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jeder muss seine eigenen Sünden tragen", description = "Der Meister kettete Kael'thas' Sündenstein mit dunklen, verderbenden Prozessen an seine Seele, wodurch Kael'thas gezeichnet und überlastet wurde.\n\nEr trägt nicht nur die Last seiner eigenen Sünden, sondern auch die der Sünden zahlloser anderer Seelen mit sich herum. Das wäre sogar für die edelsten Seelen eine erdrückende Last, und Kael'thas zählt sicher nicht dazu.\n\nHoffen wir, dass die Zeit, die Ihr mit Kael'thas verbracht habt, seine Seele auf mein Ritual vorbereitet hat.\n\nIch muss diese verfluchte Last aufheben, indem ich seine Seele von fremden Sünden befreie, oder wir verlieren ihn für immer.", sourceObjective = "Schließt das Extraktionsritual bei Kael'thas Sonnenwanderer ab.", completion = "Ich kann es nicht guten Gewissens einen Erfolg nennen, aber es ist wahrscheinlich das beste Ergebnis, auf das wir hoffen konnten. Die eigenen Sünden zu tragen, ist keine leichte Aufgabe, aber es kann sehr befreiend sein.\n\nNehmt diese Kette, wenn Ihr wollt. Zeigt allen, dass Ihr zu Euren Sünden steht. Kael'thas hat keine Verwendung mehr für sie.", sourceObjectiveStatus = "unverified-source-field" }
quests[58388] = { id = 58388, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwärzeleidverräter", description = "Bei seinem letzten Gefecht am Finsterwallturm bat der Prinz viele der adligen Häuser hier aus dem Kelchdistrikt um Hilfe.\n\nEr erhielt keine.\n\nDie meisten vermieden einfach den Konflikt... aus reinem Selbstschutz. Eine schändliche, obgleich verständliche Entscheidung.\n\nEin Haus handelte allerdings. Lord Schwärzeleid reagierte mit grausamem Spott und entsandte seine Steingeborenen, um stattdessen die Armeen des Meisters zu unterstützen.\n\nPrinz Renathal hat diesen Verrat nicht vergessen.\n\nKael'thas sucht nach Vergeltung? Gebt sie ihm. Beginnt mit den Steingeborenen.", sourceObjective = "Tötet 4 Schwärzeleidaufseherinnen.", completion = "Hat irgendeiner der Schwärzeleidventhyr Zeichen von Reue gezeigt?\n\nWir hatten gehofft, einige von ihnen schließlich doch für unsere Sache rekrutieren zu können.", sourceObjectiveStatus = "unverified-source-field" }
quests[58389] = { id = 58389, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maldraxxische Waffen", description = "<Die Waffe, die Ihr findet, ähnelt keiner der Waffen, die die meisten Venthyr bei sich führen, und doch trägt sie Markierungen, die unverkennbar sind...\n\nEs wäre klug, noch weitere solche Waffen zu finden und sie der Anklägerin zu bringen.>", sourceObjective = "Sammelt 8 maldraxxische Waffen.", progress = "Was habt Ihr da bei Euch? Die gehören nicht hierher...", completion = "Die Schwärzeleidventhyr führen Waffen der maldraxxischen Armee?\n\nDas würde bedeuten...", sourceObjectiveStatus = "unverified-source-field" }
quests[58391] = { id = 58391, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erkundung... für meine, äh, Erholung", sourceObjective = "Spioniert das Treffen des Zehntherrn mit seinem maldraxxischen Kontakt aus.", completion = "Ein Lich? So nahe?\n\nSpürt Ihr seine Gegenwart? Ich konnte das früher...", sourceObjectiveStatus = "unverified-source-field" }
quests[58392] = { id = 58392, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zerstörung von Todesende", sourceObjective = "Vernichtet das maldraxxische Lager in Todesende.", completion = "Verräter und Feiglinge. Für beide ist mir meine Zeit zu schade!", sourceObjectiveStatus = "unverified-source-field" }
quests[58393] = { id = 58393, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Strategische Liquidierungen", description = "Ich gestehe, dass ich mir das ganze Ausmaß möglicher Konsequenzen nicht ausmalen kann, die durch die Vereinbarung des Zehntherrn, Anima zu teilen, angerichtet wurden.\n\nAber ich bin mir vollkommen der Gefahren bewusst, die ein Lich mit Zugriff auf Macht darstellt.\n\nAußerdem weiß ich, dass es der Anklägerin wichtig ist, diese Situation zu klären. Angesichts meiner aktuellen Lage ist es deswegen auch wichtig für mich.\n\nWir sollten denjenigen, die für die Logistik des Animatransfers verantwortlich sind, ein paar Knüppel zwischen die Beine werfen. Das sollte die Lieferungen zum Stillstand bringen.", sourceObjective = "Tötet Gräberriesen in Todesende.", completion = "Je größer sie sind... desto größer ist die Explosion am Ende. Ha!", sourceObjectiveStatus = "unverified-source-field" }
quests[58394] = { id = 58394, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lady Ouix'Ara", description = "Spürt Ihr das? Den Frost in Euren Knochen... die Energie... Macht...\n\nSie ist hier. Der Lich.\n\nBringt mich zu ihr. Ich muss mit ihr sprechen... auf meine Weise.", sourceObjective = "Tötet Lady Ouix'Ara.", progress = "Ein Lich hat noch nie etwas Gutes bedeutet, {name}.", completion = "Es war unwahrscheinlich, dass sie uns etwas Brauchbares sagen würde, aber ich musste es versuchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[58395] = { id = 58395, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Genug Rache für einen Tag", description = "Nachdem der Sonnenbrunnen zerstört und mein Volk fast ausgelöscht wurde, habe ich geschworen, mich an Arthas und Kel'Thuzad zu rächen. Aber dazu brauchte ich Macht, und um diese Macht zu erreichen...\n\n<Kael'thas wird still.>\n\nIch... bin bereit, nach Sündensturz zurückzukehren. Für das, was vor mir liegt, muss ich meine Macht wiedererlangen.\n\nWie die Anklägerin so gern wiederholt... Es gibt vieles, worüber ich nachdenken muss.\n\nLasst uns unsere Verbündeten über die Offenbarung unseres Feindes in Kenntnis setzen.", sourceObjective = "Bringt Kael'thas nach Sündensturz und meldet Euch bei Prinz Renathal.", completion = "Maldraxxus ist verpflichtet, Revendreth vor auswärtigen Eindringlingen zu beschützen, und nicht unsere Anima für eigene Zwecke abzuschöpfen.\n\nNehmt dieses Geschenk als Dank für Eure Hilfe dabei, dieses Komplott ans Licht zu bringen, {name}.\n\nWir werden Zeit brauchen, um unseren nächsten Schritt zu planen, aber ich bin mir sicher, dass Ihr in dem Plan eine Schlüsselrolle einnehmen werdet.", sourceObjectiveStatus = "unverified-source-field" }
quests[58406] = { id = 58406, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spiegel nach Maldraxxus", description = "Mir ist zu Ohren gekommen, dass Laurent bei seinen Reparaturen deutliche Fortschritte gemacht hat.\n\nSobald der Spiegel wiederhergestellt ist, können wir unsere Bestrebungen, das letzte Medaillon zu bergen, endlich in die Tat umsetzen.\n\nBegebt Euch zum Bollwerk und seht, ob seine Arbeit bald beendet ist.", sourceObjective = "Findet Laurent auf dem Bollwerk von Sündensturz.", completion = "Dieser Spiegel ist meine größte Errungenschaft. Er stellt eine Verbindung direkt in die Nekropole her, die über den Knochenfeldern von Maldraxxus schwebt.", sourceObjectiveStatus = "unverified-source-field" }
quests[58407] = { id = 58407, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Medaillon der Herrschaft", description = "Laurent spricht die Wahrheit. Wir dürfen keine Zeit verlieren.\n\nDieser Spiegel ist unser Eingang ins Herz von Maldraxxus.\n\nZusammen mit Kael'thas werden wir Kel'Thuzad finden und ihm das Medaillon der Herrschaft aus den unwürdigen Fingern reißen.", sourceObjective = "Benutzt Laurents Spiegel, um nach Maldraxxus zu gelangen und Kel'Thuzad das Medaillon der Herrschaft zu entreißen.", completion = "Revendreth kann sich jetzt wieder seiner wahren Aufgabe widmen. Mögen wir gemeinsam einer besseren Zukunft entgegensehen.\n\n<Prinz Renathal lächelt.>\n\nUnd mein treuer Gargon Vrednic hat Euch wohl ebenfalls in sein Herz geschlossen.\n\nWenn Ihr ihn möchtet, würde er Euch sicher gern begleiten. Gemeinsam werdet Ihr Angst und Schrecken verbreiten, wenn er Euch in unsere nächste Schlacht trägt.", sourceObjectiveStatus = "unverified-source-field" }
quests[58420] = { id = 58420, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Übles Ärgernis", description = "Die Ho-zen sind schwächliche Opportunisten. Es verwundert mich nicht, dass sich einige von ihnen den Alten Göttern angeschlossen haben.\n\nWir sollten uns um sie kümmern, bevor sie sich zu einer echten Bedrohung entwickeln.", sourceObjective = "Tötet 7 Oktopusschwanz-Ho-zen im Tal der Ewigen Blüten.", completion = "Gut. Das Tal braucht ihren Schmutz nicht.", sourceObjectiveStatus = "unverified-source-field" }
quests[58421] = { id = 58421, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spezieller Zugang", description = "Mateo wird die andere Spiegelscherbe haben, und wir brauchen das Medaillon. Wahrscheinlich befindet er sich auf meinem früheren Anwesen in Archivam.\n\nEs wird von Nourman, einem loyalen Gräber, bewacht. Nourman ist immer sehr pflichtbewusst, was auch immer um ihn herum geschieht.\n\nMateo hat wahrscheinlich dieselben Regeln für den Zugang zum Anwesen beibehalten: Man muss die Fangzähne derer besitzen, denen Zugang gewährt wurde. Wenn Ihr Euch die Fangzähne von den Kommandanten seiner Operation besorgt, wird Nourman Euch passieren lassen.", sourceObjective = "Besorgt die Fangzähne von Prüferin Daciana, Prüfer Boian und Prüferin Ionata.", progress = "Heda, wollt Ihr Zugang zum Anwesen? Zeigt mir Eure Fangzähne.", completion = "<Nourman sieht sich die Fangzähne genau an.>\n\nDas passt. Merkwürdig, dass Ihr so viele davon habt.\n\nHört mal, Ihr seht aber nicht wie ein Venthyr aus.\n\n<Nourman zuckt mit den Schultern.>\n\nMir soll's egal sein. Ihr habt die Fangzähne, Ihr dürft rein. So sind die Regeln.", sourceObjectiveStatus = "unverified-source-field" }
quests[58422] = { id = 58422, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zeichen der Eroberer", description = "Die einfallenden Diener von N'Zoth nehmen sich Ländereien, die ihnen nicht zustehen.\n\nDas Tal wird nicht erobert werden, solange auch nur ein Rajani noch atmet.\n\nVerbrennt ihre Banner und setzt unseren Anspruch durch.", sourceObjective = "Verbrennt 6 Banner des Schwarzen Imperiums im Tal der Ewigen Blüten.", completion = "Gut.\n\nDiese Eindringlinge sollten wissen, dass wir uns nicht so einfach erobern lassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[58423] = { id = 58423, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Stärksten unter ihnen", description = "Ihr habt bei Euren Eroberungen große Stärke bewiesen, aber jeden Tag greifen neue Feinde das Tal an.\n\nFindet die stärksten Feinde unter ihnen und besiegt sie, auf dass ihre Verbündeten es alle sehen können.", sourceObjective = "Besiegt 3 seltene Diener von N'Zoth im Tal der Ewigen Blüten.", completion = "Es bringt selbst Diener der Alten Götter zum Innehalten, wenn ihre besten Kämpfer tot vor ihnen liegen.\n\nVergesst das nicht, solange die Schlacht tobt.", sourceObjectiveStatus = "unverified-source-field" }
quests[58424] = { id = 58424, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auge um Amulett", description = "Archivam wurde von Denathrius' Lakaien überrannt.\n\nWir müssen diese Eindringlinge beseitigen. Es sieht so aus, als ob sie Archivam bis auf die Grundmauern niederreißen, um nach Spuren des Medaillons der Kuratorin zu suchen.\n\nGeht, {name}. Haltet sie auf, bevor es zu spät ist.", sourceObjective = "Tötet 12 Archivameindringlinge und 5 Ausgrabungsvollstrecker in Archivam.", completion = "Ja! Der Rest dieser Ratten wird es sich jetzt zweimal überlegen, mit Denathrius zusammenzuarbeiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[58426] = { id = 58426, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Schatten unseres Versagens", description = "Ich werde mich höchstpersönlich um die Absolution von Kael'thas Sonnenwanderer kümmern. Sein derzeitiger Zustand und sein Trauma benötigen nicht weniger als perfekte Intervention und Anleitung, um behandelt zu werden.\n\nEure Hilfe wäre mir dabei sehr willkommen. Ich spüre eine Verbindung zwischen Kael'thas und Euch. Ich denke, Eure Anwesenheit könnte ihn dazu bewegen, einen besseren Pfad einzuschlagen.\n\nWenn Ihr dazu bereit seid, trefft uns am Finsterwallturm.\n\nPrinz Renathal hat dort einst eine schwere Niederlage erlitten. Vielleicht lässt sich dieses Mal ein besseres Schicksal finden.", sourceObjective = "Trefft Euch mit der Anklägerin und Kael'thas am Finsterwallturm.", completion = "Es freut mich, dass Ihr gekommen seid. Fangen wir an.", sourceObjectiveStatus = "unverified-source-field" }
quests[58428] = { id = 58428, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gruftknacker", description = "Eines vergaß ich zu erwähnen. Verzeiht, {name}.\n\nDer Spiegel ist absichtlich und inhärent verflucht, sobald er zusammengesetzt wird.\n\nIhr müsst mein Todeslotuspulver finden. Es war in einer der Gruften in Archivam, aber ich weiß nicht mehr, in welcher.\n\nIch fürchte, Ihr werdet sie alle durchprobieren müssen, {name}.", sourceObjective = "Sammelt Steinbrecherhämmer, um Grufttüren auf der Suche nach Todeslotuspulver aufzubrechen.", progress = "Habt Ihr das Pulver?", completion = "Ausgezeichnet. Jetzt können wir den Spiegel gefahrlos betreten.", sourceObjectiveStatus = "unverified-source-field" }
quests[58431] = { id = 58431, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trankvorrat", description = "Ich werde Euch über den Trankvorrat aufklären. Die Tränke, die wir hier kreieren, haben eine Reihe positiver Effekte.\n\nTötet die Schleime in den Ruinen in der Umgebung und sammelt die triefende Zutat: viskoses Öl, die sie möglicherweise hinterlassen Jeder Schleim kann große Mengen dieses Öls produzieren, also könnt Ihr immer nur das Öl eines Schleims tragen.\n\nBringt dieses Öl zum Trankvorrat und werft es hinein.", sourceObjective = "Bringt drei triefende Zutaten: viskoses Öl zum Trankvorrat.", progress = "Habt Ihr genug Öl dabei?", completion = "Teilen wir uns alle dieses fabelhafte Gebräu, das Ihr erschaffen habt!", sourceObjectiveStatus = "unverified-source-field" }
quests[58432] = { id = 58432, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Etwas Altes, etwas Gebrauchtes", description = "Wollt Ihr neue Glücksbringer? Chordy ist der beste Glücksbringerfinder!\n\nWollt Ihr Euch mit Chordy umsehen?\n\n<Chordy blickt Euch mit seinem großen Auge flehend an.>", sourceObjective = "Findet und sammelt mit Chordy 10 Stücke wertvolles Bergungsgut in Maldraxxus.", progress = "Haben wir etwas Gutes gefunden?", completion = "Das sind wertvolle Ressourcen. Danke, Schlundgänger.", sourceObjectiveStatus = "unverified-source-field" }
quests[58433] = { id = 58433, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Animaabnahme", description = "Es geht dabei nicht um einen einfachen Überfall oder Protest. Diese Steingeborenen wollten die Anima von diesem Konvoi stehlen.\n\nDieser Animazehnt sollte zum Meister gebracht werden. Es herrscht eine Dürre und wir können nicht zulassen, dass diese Vagabunden und Schurken unsere schwer verdiente Anima stehlen.\n\nHolt den Zehnt nach Möglichkeit zurück, dann will ich sehen, was ich für Eure Reputation tun kann.", sourceObjective = "Findet den Animakanister.", progress = "Was habt Ihr entdeckt?", completion = "Gute Arbeit, Sterblicher. Steingeborene benötigten Anima, um zu existieren. Ohne sie verwandeln sie sich zurück in Stein. Dieser Verlust trifft sie härter als dreißig tote Soldaten auf ihrer Seite.", sourceObjectiveStatus = "unverified-source-field" }
quests[58435] = { id = 58435, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tradition der Vulpera", description = "Die Horde erkennt dank Eurer Anstrengungen jetzt endlich den Wert der Vulpera.\n\nIhr seid... mehr Vulpera als viele, die ich kenne!\n\nTrefft mich im Vulperaversteck in Vol'dun. Kiro hat mir aufgetragen, als Dank für Eure Mühen ein kleines Andenken zusammenzustellen.", sourceObjective = "Trefft Hagashi im Vulperaversteck in Vol'dun.", completion = "Euer Abenteuerinstinkt, Eure Fertigkeiten und Euer Forscherdrang machen uns so stolz. Die Horde kann froh sein, uns zu haben!\n\nDenkt daran, {name}, und nehmt dieses Geschenk. Ihr tragt uns mit Euch, wo immer Ihr auch seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[58436] = { id = 58436, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tradition der Mechagnome", description = "{name}, wir könnten mit Eurem Fortschritt nicht zufriedener sein. Ihr repräsentiert uns würdig in der Allianz.\n\nKehrt zur Stadt Mechagon zurück, sobald Ihr Gelegenheit dazu habt. Waren hat ein Geschenk für Euch.", sourceObjective = "Sucht Prinz Erazmin in der Stadt Mechagon auf.", completion = "Macht so weiter, dann wird die Entwicklung unseres Volkes mit unglaublicher Geschwindigkeit voranschreiten.\n\nEs gibt noch so viel zu entdecken! Lernt und wachst weiter, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[58437] = { id = 58437, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teile für ein Ganzes", description = "Damien hat große Träume, aber ohne weitere Monstrositäten wird diese Übungseinrichtung keinen Erfolg haben! \n\nAber ich habe einen Plan! Wenn wir keine weitere Monstrositäten rekrutieren können, machen wir sie einfach selbst!\n\nIhr müsst mir einige Leichname besorgen und sie für die Verwertung mit einer Fahne markieren. Den Rest erledige ich.", sourceObjective = "Markiert 15 Leichname für die Verwertung", sourceObjectiveStatus = "unverified-source-field" }
quests[58438] = { id = 58438, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verschlingendes Maul" }
quests[58439] = { id = 58439, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verschlingendes Maul" }
quests[58440] = { id = 58440, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spieglein, Spieglein...", description = "Wir haben, was wir brauchen, um Euch hindurchzubringen, {name}.\n\nMein Medaillon liegt auf der anderen Seite des Spiegels. Sobald Ihr hindurchgegangen seid, wird es dort sein... irgendwo.\n\nBitte, seid vorsichtig. Mein Geist mag geschwächt sein, aber ich erinnere mich daran, mit der Anklägerin zusammengearbeitet zu haben, um das Innere der Gruft zu schützen.\n\nEigentlich sollte ich Euch alles über diesen Ort sagen können, aber ich fürchte, das ist nicht mehr der Fall.", sourceObjective = "Geht durch den Spiegel der Kuratorin. Nehmt dann das Medaillon der Habsucht an Euch.", progress = "Mein Medaillon? Habt Ihr es?", completion = "Ihr habt das Medaillon gefunden! Ich wünschte, Ihr hättet es unter besseren Umständen gefunden. Es fehlt mir, feiern zu können.\n\nAber ich sollte Euch belohnen. Ja, eine Belohnung! Hier, nehmt die hier. Mögen sie Euch gute Dienste leisten!", sourceObjectiveStatus = "unverified-source-field" }
quests[58442] = { id = 58442, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verschlingendes Maul" }
quests[58443] = { id = 58443, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Begleitende Betreuung von Kael'thas", description = "Kael'thas ist von der verzerrten Verderbnis des Meisters befreit, aber er ist noch nicht wirklich \"frei\".\n\nEr trägt mehr als genug Last durch seine eigenen Sünden mit sich herum, um ihn in den Schlund zu verdammen.\n\nWir müssen ihn sorgsam dazu ermutigen und dazu bringen, für seine Fehler Buße zu tun. Wenn er die vielen Fehler aus seinem sterblichen Leben nicht wiedergutmachen kann, wird er auf ewig verdammt sein.\n\nIhr habt einen guten Einfluss auf ihn. Bitte begleitet uns für seine nächste Lektion hinunter in den Kelchdistrikt.", sourceObjective = "Trefft die Anklägerin und Kael'thas im Kelchdistrikt.", completion = "Wir sind bereit für die nächste Lektion.", sourceObjectiveStatus = "unverified-source-field" }
quests[58444] = { id = 58444, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr nach Sündensturz", description = "{name}, wir müssen das Medaillon so schnell wie möglich zurück nach Sündensturz bringen.\n\nWir haben ja gesehen, wie schlagkräftig die Streitkräfte von Mateo waren. Kaum vorstellbar, was für Verheerungen Denathrius anrichten könnte, wenn wir weitere Zeit verschwenden.\n\nIch kehre in Kürze zur Gruft der Absolution zurück. Dank all Eurer Arbeit kann ich beginnen, meinen Pflichten wieder nachzugehen.\n\nAls Erstes werde ich einen neuen Sündenhüter rekrutieren. Ach, wie es mir vor den Vorstellungsgesprächen graut...", sourceObjective = "Bringt das Medaillon zu Prinz Renathal in Sündensturz.", progress = "Habt Ihr das Medaillon der Habsucht?", completion = "Ausgezeichnete Arbeit, {name}.\n\nDa wir das Medaillon der Kuratorin in Händen halten, sind wir dem Sieg einen Schritt näher gekommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[58445] = { id = 58445, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eindämmung der Nacht", description = "Zum Glück seid Ihr hier, {name}.\n\nThiernax glaubt, dass er vielleicht weiß, wie er Tyrande vor dem Schicksal retten kann, das er selbst als Nachtkrieger erlitten hat.\n\nLasst uns hören, was er zu sagen hat.", sourceObjective = "Hört Euch Thiernax' Plan an.", completion = "Thiernax schlägt einen kühnen Plan vor. Es wird nicht leicht sein, die anderen ehemaligen Nachtkrieger ausfindig zu machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[58446] = { id = 58446, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fährte des Fährtenlesers", description = "Wir werden die Hilfe eines erfahrenen Fährtenlesers benötigen, wenn wir die anderen Nachtkrieger finden wollen.\n\nDie Wilde Jagd verfügt in dieser Hinsicht über legendäre Fähigkeiten. Keine Beute kann sich ihnen entziehen.\n\nSprecht mit Lord Herne. Mit einem seiner Jäger an Eurer Seite wird Eure Suche gewiss erfolgreich sein.", sourceObjective = "Sprecht mit Lord Herne und findet einen Fährtenleser der Wilden Jagd.", completion = "Ah, ja. Ich weiß, wen Ihr meint.", sourceObjectiveStatus = "unverified-source-field" }
quests[58447] = { id = 58447, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Monsterjagd", description = "Macht Euch bereit, {class}. Wir jagen einen Weltenfresser.\n\nSie sind die größten der Verschlinger. Diese riesigen Ungetüme können einer gesamten Region in kürzester Zeit alle Anima entziehen.\n\nDa der Ardenwald unter der Dürre leidet, könnte die Anwesenheit eines Weltenfressers eine Katastrophe sein.\n\nWir dürfen uns aber nicht einfach in die Schlacht stürzen, ohne unseren Gegner vorher genau verstanden zu haben. Geht mit mir zur Ältestenwehr. Sogar solche Kreaturen hinterlassen Spuren.\n\nUnsere Beute zu verstehen wird uns ermöglichen, sie zu vernichten.", sourceObjective = "Sucht nach Hinweisen und Spuren, um mehr über den Weltenfresser zu erfahren.", completion = "Das Problem ist gerade größer geworden. Wir brauchen einen neuen Plan.", sourceObjectiveStatus = "unverified-source-field" }
quests[58449] = { id = 58449, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Säurereflux", description = "Wir müssen gut vorbereitet sein, bevor wir uns Voras stellen können.\n\nDie Verdauungssäfte der Gorm aus dem Ardenwald lösen die Anima in ihrer Nahrung auf und leiten sie ab. Wenn die Verschlinger sie zu sich nehmen, verursacht ihnen das nicht gerade wenig Beschwerden.\n\nFür ein Tier dieser Größe brauchen wir eine Menge davon, um eine Wirkung zu erzielen. In dem Nest im Osten sollten eine Menge Gorm sein.\n\nVor langer Zeit hat mir ein Handwerker ein Werkzeug gegeben und gesagt, dass es hilfreich im Kampf gegen die Gorm sei, falls es je dazu käme. Ihr dürft es Euch ausleihen.", sourceObjective = "Verwendet den Gormhirtenstock gegen die Gorm im Gormnest, um 50 pralle Verdauungssäcke einzusammeln.", progress = "Wenn wir den Weltenfresser so heftig beeinträchtigen wollen, dass wir ihn töten können, brauchen wir diese Verdauungssäcke, {name}.", completion = "<Reldorn hievt die Säcke hoch, die sich unangenehm auswölben.>\n\nSo viele? Wie groß ist denn dieses Ding, dass Ihr zwei jagt?", sourceObjectiveStatus = "unverified-source-field" }
quests[58450] = { id = 58450, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Animainstinkte", description = "Voras streift offensichtlich gerne in der Ältestenwehr herum. Wir müssen einen Weg finden, um ihn anzulocken, sobald wir bereit für den Kampf sind.\n\nHabt Ihr die Wildsamen auf der Lichtung bemerkt, wo wir ihn gesehen haben? Voras labt sich gewiss an der konzentrierten Anima, die darin enthalten ist.\n\nEs gibt im Gormnest bestimmt noch einige verbrauchte Wildsamen aus der Zeit vor der Dürre. Lasst uns einen Köder herstellen, den Voras nicht ignorieren kann, und ihn in unsere Falle locken.", sourceObjective = "Sammelt 8 lebensgestählte Anima.", progress = "Vielleicht sind mehrere Wildsamen nötig, aber mit genug konzentrierter Anima sollten wir Voras hervorlocken können.", completion = "Es erstaunt mich, dass darin so viel konzentrierte Anima enthalten ist. Damit werdet Ihr ganz sicher einen Verschlinger anlocken!", sourceObjectiveStatus = "unverified-source-field" }
quests[58451] = { id = 58451, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Voras der Weltenfresser", description = "Wir haben alles, was wir brauchen, {name}. Jetzt bleibt nur noch das Töten.\n\nWir legen den Köder aus, schwächen ihn und versetzen ihm den Todesstoß.\n\nJagd ist Willensstärke. Unser aller Leben steht auf dem Spiel. So war es schon immer, in Azeroth wie im Ardenwald.\n\nLasst die Jagd beginnen.", sourceObjective = "Tötet Voras.", progress = "Voras darf dem Ardenwald nicht weiter Anima entziehen. Wir müssen das aufhalten.", completion = "Die Jagd ist vorüber. Wir haben es geschafft.", sourceObjectiveStatus = "unverified-source-field" }
quests[58452] = { id = 58452, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schattenjagd", description = "Das Ungetüm ist tot und meine Pflicht erfüllt. Die Tirnenn können ihre Heimat leichterhand gegen kleinere Verschlinger verteidigen. Alles wird seinen natürlichen Gang gehen.\n\nIch melde mich bei Lord Herne zurück und treffe Euch beim Herz des Waldes. Dort erfahren wir, was ich als Nächstes jagen werde.", sourceObjective = "Sprecht mit Ysera im Herz des Waldes.", completion = "Selbst im Jenseits wächst die Legende von Huln Hochberg weiter.\n\nIhr habt gut daran getan, uns seiner Hilfe zu versichern, {name}. Nun lasst unsere Suche beginnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[58454] = { id = 58454, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf Krawall gebürstet", description = "Euer Animabeitrag hat unserer Unternehmung hier sehr geholfen. Einige unserer berühmteren Wettstreiter wurden vom Fluss neuer Anima hierher gelockt.\n\nMöchtet Ihr Euch gerne gegen die berühmte Sabriel beweisen? Solltet Ihr sie besiegen, würde das Profit für alle bedeuten.\n\nIch kann sie Eurem Plan hinzufügen. Sie wird sich bald zeigen, wenn Ihr die anderen Herausforderer besiegt.", sourceObjective = "Besiegt Sabriel die Knochenspalterin im Theater der Schmerzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[58455] = { id = 58455, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schattenhaftes Scharmützel", description = "Jetzt sind wir am Zug! Wir haben herausgefunden, wo sich diese schattenhaften Gestalten versteckt haben. Es ist an der Zeit, sie anzugreifen und ihre finsteren Pläne zu vereiteln. Ihre Operationsbasis befindet sich in den Schwarzfelstiefen. Es liegt jetzt an Euch.", sourceObjective = "Findet Burt Macklyn vor dem Eingang zu den Schwarzfelstiefen im Schwarzfels.", completion = "Diese schattenhaften Gestalten gehen uns schon zu lange auf die Nerven. Geht rein und setzt ihnen ein Ende.", sourceObjectiveStatus = "unverified-source-field" }
quests[58456] = { id = 58456, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schattenhaftes Scharmützel", description = "Jetzt sind wir am Zug! Wir haben herausgefunden, wo sich diese schattenhaften Gestalten versteckt haben. Es ist an der Zeit, sie anzugreifen und ihre finsteren Pläne zu vereiteln. Ihre Operationsbasis befindet sich in den Schwarzfelstiefen. Es liegt jetzt an Euch.", sourceObjective = "Findet Burt Macklyn vor dem Eingang zu den Schwarzfelstiefen im Schwarzfels.", completion = "Diese schattenhaften Gestalten gehen uns schon zu lange auf die Nerven. Geht rein und setzt ihnen ein Ende.", sourceObjectiveStatus = "unverified-source-field" }
quests[58457] = { id = 58457, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schatten des Schwarzfels", description = "Endlich haben wir diese lästigen schattenhaften Gestalten aufgespürt. Sie sollten alle hier drin sein. Sie machen einen äußerst fähigen Eindruck, deswegen schlage ich vor, nur mit Eurem besten Team hineinzugehen, falls Ihr Aussicht auf einen Sieg haben wollt.\n\nLasst es mich wissen, sobald Ihr bereit seid.", sourceObjective = "Haltet die schattenhaften Gestalten auf.", completion = "Unglaublich, Ihr habt sie aufgehalten! Der Himmel weiß, welches Chaos sie angerichtet hätten, wenn wir nicht im richtigen Moment eingegriffen hätten. Gut gemacht!", sourceObjectiveStatus = "unverified-source-field" }
quests[58458] = { id = 58458, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Haustierkampfherausforderung: Schwarzfelstiefen", description = "Diese schattenhaften Gestalten führen wieder Böses im Schilde. Wollt Ihr ihnen wirklich gegenübertreten? Wenn Ihr wirklich noch mal da reingehen wollt, werde ich Euch nicht aufhalten.", sourceObjective = "Haltet die schattenhaften Gestalten auf.", completion = "Unglaublich, Ihr habt sie aufgehalten! Der Himmel weiß, welches Chaos sie angerichtet hätten, wenn wir nicht im richtigen Moment eingegriffen hätten. Gut gemacht!", sourceObjectiveStatus = "unverified-source-field" }
quests[58460] = { id = 58460, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Würdenträger des Wahnsinn", description = "Die N'raqi sind schon lange Kommandanten und Zuchtmeister in den Streitkräften der Alten Götter. Ihre Anwesenheit auf dem Schlachtfeld beweist, dass diese Invasion koordiniert und geplant ist und nicht nur ein zufälliger Ausbruch von Verderbnis.\n\nSolange die chaotischen Truppen der Alten Götter von diesen gesichtslosen Kommandanten angeführt werden, sind sie ernstzunehmende Gegner.\n\nWir müssen diese Kreaturen zuerst ausschalten, dann gewinnen wir gegen N'Zoth vielleicht die Oberhand.", sourceObjective = "Tötet 6 gesichtslose Diener von N'Zoth im Tal der Ewigen Blüten.", completion = "Wenn wir ihre Anführer ausschalten, sollten wir N'Zoths Truppen im Tal empfindlich treffen.\n\nDas verschafft uns einen Vorteil, durch den wir sie endgültig auslöschen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[58461] = { id = 58461, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Folianten des uralten Wahnsinns", description = "In Zeiten wie diesen müssen alle Bewohner des Tals zusammenrücken und ihren Teil beitragen. Leider war ich nie wirklich ein Kämpfer, deswegen ist mein Nutzen in Kriegszeiten nur begrenzt.\n\nIch kann aber trotzdem helfen. Wir wissen nicht viel über die Gegner, denen wir gegenübertreten, und Wissen ist Macht, wie jeder weiß.\n\nIch glaube, ich habe gesehen, wie einige der K'thir Folianten bei sich trugen. Könnt Ihr mir einige davon bringen? Dann kann ich aus den Schriften vielleicht nützliche Informationen ziehen.", sourceObjective = "Sammelt 8 Folianten des uralten Wahnsinns von Einheiten der K'thir im Tal der Ewigen Blüten.", progress = "Habt Ihr die Folianten beschaffen können?", completion = "Ja, genau danach habe ich gesucht. Ich werde sie sofort auswerten!\n\nEndlich bin ich wieder nützlich!", sourceObjectiveStatus = "unverified-source-field" }
quests[58462] = { id = 58462, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fenster zur Seele", description = "Als ob die tödlichen Angriffe unseres Feindes nicht schon genug wären, quälen seine Diener auch die Herzen unserer Verteidiger.\n\nIch rede natürlich von den Augen. Sie starren direkt in die Seelen unserer Krieger und nutzen ihre schlimmsten Ängste gegen sie.\n\nWenn wir uns auch nur eine minimale Chance auf einen Sieg bewahren wollen, müssen wir die Augen ausschalten.", sourceObjective = "Tötet 6 Augen des Imperiums im Tal der Ewigen Blüten.", progress = "Ist Eure Aufgabe abgeschlossen?", completion = "Die schändlichen Augen sind Geschichte und unsere Soldaten schöpfen neuen Mut.\n\nHabt Dank, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[58463] = { id = 58463, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bestien des Wahnsinns", description = "Zu sehen, wie sich das Tal der Ewigen Blüten vom Sha erholt und wieder erblüht, nur um dann von den Alten Göttern abermals besudelt zu werden, bringt mein Blut in Wallung!\n\nWir müssen die Verderbnis der Alten Götter ausmerzen, bevor sie sich in diesem Land erneut festsetzen kann. Ich habe die Fleischbestien gesehen, die mit N'Zoths Truppen marschieren und auf Schritt und Tritt seine Verderbnis verbreiten.\n\nStellt sicher, dass das ein Ende hat.", sourceObjective = "Tötet 10 Fleischbestien im Tal der Ewigen Blüten.", completion = "Das habt Ihr gut gemacht.\n\nN'Zoth darf dieses Land niemals besitzen!", sourceObjectiveStatus = "unverified-source-field" }
quests[58464] = { id = 58464, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tiefenbautilgung", description = "Eine Sekte des Mantisschwarms namens \"Tiefenbau\" hat die Großblütenmine besetzt. Dieser Mantisschwarm hat sich vollkommen der Verderbnis der Alten Götter ergeben, was ihn zu einem extrem gefährlichen Gegner macht.\n\nWir können nicht zulassen, dass diese Mantis im Tal Amok laufen. Ihr wisst, was zu tun ist.", sourceObjective = "Tötet 10 Tiefenbaumantis in der Großblütenmine im Tal der Ewigen Blüten.", completion = "Die Mantis kommen unentwegt, aber wir werden sie zurückschlagen.\n\nZum Glück habt Ihr Euch um den Großteil der Bedrohung gekümmert.", sourceObjectiveStatus = "unverified-source-field" }
quests[58465] = { id = 58465, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Manifestation der Verderbnis", description = "Die Verderbnis der Alten Götter ist oft so schändlich, dass sie sich in physischer Gestalt manifestiert.\n\nDas hat sich schon bei den Sha gezeigt. Diesmal ist es nicht anders.\n\nLöscht diese Verderbnis aus, wo immer Ihr sie auch antrefft. Sie darf sich nicht ausbreiten.", sourceObjective = "Tötet 8 faulige Sekrete im Tal der Ewigen Blüten.", completion = "Ich kann den Schmutz von N'Zoths Verderbnis auf Euren Waffen sehen.\n\nGut gekämpft, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[58466] = { id = 58466, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Qual aus dem Jenseits", description = "Es ist schon schlimm genug, dass N'Zoth die Lebenden im Tal unterjochen will, aber jetzt will er auch noch die Toten auf seine Seite ziehen!\n\nDie Shado-Pan haben schon alle Hände voll zu tun, die Lebenden zu verteidigen. Können wir darauf vertrauen, dass Ihr diesem schändlichen Treiben ein Ende setzt?", sourceObjective = "Befreit 6 uralte Pandarengeister im Tal der Ewigen Blüten.", completion = "Ich hatte gegen Euer Volk zuerst Vorbehalte, aber anscheinend habt Ihr wirklich das Wohlergehen von Pandaria im Herzen.\n\nIch danke Euch, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[58467] = { id = 58467, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefangene in Geist und Körper", description = "N'Zoths Truppen sind ganz plötzlich im Tal eingefallen. Als ich mit meinen Shado-Pan hier eintraf, waren bereits viele vom Goldenen Lotus von den Streitkräften des Alten Gottes gefangen genommen worden.\n\nMit vereinten Kräften haben wir es gerade so geschafft, die Eindringlinge daran zu hindern, mehr unserer Brüder gefangen zu nehmen. Die, die allerdings schon in Gefangenschaft waren, befinden sich immer noch in den Klauen des Alten Gottes.\n\nIch weiß, dass wir unsere Differenzen hatten, {name}, aber wenn Ihr uns bei der Rettung helfen könntet, würden die Shado-Pan tief in Eurer Schuld stehen.", sourceObjective = "Rettet 6 gefangene Pandaren im Tal der Ewigen Blüten.", progress = "Gibt es Neuigkeiten von den Gefangenen?", completion = "Ich möchte gar nicht an das Schicksal denken, dass sie ereilt hätte, wärt Ihr nicht zu ihrer Rettung erschienen.\n\nIhr seid ein wahrer Champion von Pandaria, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[58468] = { id = 58468, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine heranwachsende Dunkelheit", description = "Die Späher der Shado-Pan haben Hinweise auf eine neue Brutstätte der Mantis in der Großblütenmine gefunden. Anscheinend wollen diese Mantis eine neue verderbte Brut erschaffen, die N'Zoth dienen soll.\n\nWenn diese Eier schlüpfen, könnte ein neuer Schwarm mit der Macht des Alten Gottes den Himmel über dem Tal verdunkeln und Pandaria in Dunkelheit stürzen.\n\nWir werden das doch wohl nicht zulassen, oder?", sourceObjective = "Tötet 6 verderbte Inkubatoren in der Großblütenmine im Tal der Ewigen Blüten.", completion = "Der Schwarm hat sich vorerst zurückgezogen.\n\nAchtet weiter auf neue Brutstätten. Wir dürfen die Tiefenbaumantis nicht aus den Augen lassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[58469] = { id = 58469, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Risse im Tal", description = "N'Zoths Einfluss im Tal wächst, und unsere Realität beginnt zu zerfallen.\n\nDie Macht des Alten Gottes hat Risse im Gewebe unserer Realität erschaffen, die seine Diener als Tore nutzen, um uns von seinem dunklen Reich aus zu überrennen.\n\nSolange diese Risse existieren, werden wir uns niemals aus N'Zoths Griff befreien können. Schließt sie und lasst seine Verderbnis versiegen!", sourceObjective = "Schließt 3 Leerenrisse im Tal der Ewigen Blüten.", completion = "Die Durchgänge sind verschlossen, und das Tal ist wieder in seiner Realität zurück.\n\nDanke, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[58470] = { id = 58470, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verderbte Raritäten", description = "Das Schwarze Imperium ist eine ernste Gefahr für Pandaria, aber wir können das zu unserem Vorteil nutzen!\n\nObwohl wir ihnen schon oft gegenüberstanden, wissen wir kaum etwas über die Alten Götter oder N'Zoths mysteriöses Reich namens Ny'alotha.\n\nBeim Studium der alten Zivilisationen stützen wir uns oft auf Artefakte, um die tiefsten Geheimnisse, die im Laufe der Zeit verloren gegangen sind, zu enträtseln. Vielleicht findet Ihr solche Artefakte bei den Streitkräften des Alten Gottes?\n\nEs schadet nicht, mal nachzuschauen, oder?", sourceObjective = "Sammelt 3 Artefakte des Schwarzen Imperiums aus Truhen des Schwarzen Imperiums im Tal der Ewigen Blüten.", progress = "Habt Ihr etwas Interessantes gefunden?", completion = "Wundervoll! Denkt nur an die uralten Geheimnisse, die uns diese Artefakte zu enträtseln helfen!\n\nIch hoffe, es war nicht allzu schwierig, sie zu besorgen.", sourceObjectiveStatus = "unverified-source-field" }
quests[58471] = { id = 58471, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aggressive Anmerkungen", description = "Trotz der Ursprünge der Sha bei den Alten Göttern wissen wir in Pandaria nur wenig über diese.\n\nIch möchte die Gelegenheit nutzen, alle Informationen, derer ich habhaft werden kann, dem Archiv der Lehrensucher hinzuzufügen. Natürlich ist das ein wenig problematisch, wenn sie versuchen, uns zu töten.\n\nFür Euch scheint das allerdings kein Problem zu sein. Könnt Ihr mir einen Gefallen tun und ein paar Notizen darüber machen, was Ihr da draußen seht? Es würde uns immens weiterhelfen, unseren Gegner besser zu verstehen.", sourceObjective = "Nutzt das Notizbuch des Lehrensuchers, um Informationen über die Gesichtslosen, die K'thir und die Fleischbestien im Tal der Ewigen Blüten zu sammeln.", completion = "Fantastisch! Sehr sorgfältig!\n\nIch muss Euch jedoch fragen, wie Ihr in der Hitze der Schlacht eine so tadellose Schreibkunst praktizieren könnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[58472] = { id = 58472, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Waffen nieder", description = "Die Maldraxxi mühen sich direkt hinter uns ab. Es ist mir egal, ob Ihr sie als Verbündete oder Verräter anseht, solange Ihr sie aus Revendreth vertreibt.\n\nZerschlagt ihr Lager. Säubert unsere Erde davon und stellt sicher, dass so ein Frevel nie wieder vorkommt.\n\nWie Ihr das anstellt, ist egal. Es zählt nur, dass die Ketzer nie vergessen werden, was passiert, wenn sie mit wahrer Macht herumspielen.", sourceObjective = "Vernichtet das maldraxxische Lager in Todesende.", completion = "Dies soll unser Ehrgefühl beweisen.", sourceObjectiveStatus = "unverified-source-field" }
quests[58473] = { id = 58473, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Echos von Tirna Noch", description = "Es ist eindeutig, dass wir mehr Anima brauchen, als dieser Hain hervorbringen kann. Eventuell weiß ich, wie wir mehr bekommen.\n\nViele der maskierten Fae haben aus unbekannten Gründen Anima gesammelt. Ich schlage vor, dass wir sie uns zurückholen.\n\nDie Wilde Jagd hat sie bis nach Tirna Noch verfolgt... meinem ehemaligen Hain.\n\nEs ist lange her, dass ich unter seinen Ästen gewandelt bin. Nicht seitdem er verwelken musste, damit andere Haine überleben konnten.\n\nIch erinnere mich noch gut...", sourceObjective = "Trefft Euch mit Ara'lon in Tirna Noch.", completion = "Ich hätte nie gedacht, dass ich nach Tirna Noch zurückkehren würde. Dieser Ort ist voller Erinnerungen. Und voller Reue...\n\nAber wir haben keine Zeit für Sentimentalitäten. Jetzt ist es Zeit, zu handeln.", sourceObjectiveStatus = "unverified-source-field" }
quests[58476] = { id = 58476, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Donner zieht heran", description = "Die ganzen Moguklans sind sicherlich beeindruckend, aber die Zan-Tien stellen für den Goldenen Lotus die unmittelbarste Gefahr dar.\n\nSelbst jetzt steigt die Anzahl ihrer Einheiten vor der Goldenen Pagode immer weiter. Viele unserer Krieger sind unerfahren und nicht schlachterprobt. Einem Angriff der Mogu können sie nicht lange standhalten.\n\n<Ein erfahrener/Eine erfahrene:c> {class} wie Ihr könnte in diesem Kampf entscheidend eingreifen.\n\nKönnt Ihr helfen?", sourceObjective = "Tötet 12 Mogu der Zan-Tien im Tal der Ewigen Blüten.", completion = "Heute habt Ihr sicher die Leben vieler Krieger des Goldenen Lotus gerettet.", sourceObjectiveStatus = "unverified-source-field" }
quests[58477] = { id = 58477, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Durch Blut und Dreck und Knochen", description = "Die Dokani denken, dass sie stark genug sind, die uralte Magie der Anima zu nutzen, aber ihre Golems und Manifestationen stellen nur einen Bruchteil der wahren Macht der Anima dar.\n\nEntledigt sie ihrer so geschätzten Substanz, damit die Rajani sie einem besseren Nutzen zuführen können.", sourceObjective = "Sammelt 100 Animakügelchen von Mogu der Dokani und ihren Verbündeten im Tal der Ewigen Blüten.", progress = "Was habt Ihr uns mitgebracht?", completion = "Das sollte reichen.\n\nGeht jetzt. Ich bin sicher, man braucht Euch auch woanders.", sourceObjectiveStatus = "unverified-source-field" }
quests[58478] = { id = 58478, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kein Stein bleibt ganz", description = "Als die verfeindeten Klans im Tal ankamen, hielten sich die Baruk für würdig, Anspruch auf die uralte Stätte von Guo-Lai zu erheben.\n\nSie sind es aber nicht.\n\nZeigt diesen Eindringlingen, wo ihr Platz ist, und Ihr verdient Euch ein wenig Respekt bei den Rajani.", sourceObjective = "Tötet 10 Mogu der Baruk im Tal der Ewigen Blüten.", completion = "Die Baruk werden unter dem Fuß der Rajani bald lernen, sich unterzuordnen.\n\nGut gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[58479] = { id = 58479, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blitzeinschläge", description = "Die Zan-Tien nehmen gern für sich in Anspruch, die Macht der Stürme gemeistert zu haben, und doch müssen sie auf Maschinen zurückgreifen, um sich Blitze aus dem Himmel zunutze zu machen.\n\nZeigt diesen Blendern, dass die wahre Macht über Sturm und Donner aus dem Inneren stammt. Zerbrecht ihre Spielzeuge und dann sehen wir, wie es ihnen ohne sie ergeht.", sourceObjective = "Vernichtet 6 Blitzableiter im Tal der Ewigen Blüten.", completion = "Ha! Dann schauen wir mal, wie diese sogenannten \"Meister der Stürme\" ohne ihre kostbaren Apparaturen zurechtkommen!\n\nDas könnte unterhaltsam werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[58480] = { id = 58480, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Wurzeln lesen", description = "Als mein Hain verwelkte, folgte ich dem Ruf der Königin und schloss mich der Wilden Jagd an.\n\nMan kann nichts für Tirna Noch tun. Doch es schmerzt mich, dass es dort nur so vor den Feinden des Waldes wimmelt.\n\nWir brauchen eine große Menge Anima. Die maskierten Fae müssen sie irgendwo im Hain gebunkert haben... wir müssen sie nur finden.\n\nSie haben bestimmt Seelennetze verwendet, um die Anima zu sammeln und zu transportieren. Wenn ich sie untersuchen kann, sollte ich die Spur aufnehmen können.", sourceObjective = "Untersucht die ausgelaugten Seelennetze in Tirna Noch, um die höchste Animakonzentration im Hain zu finden.", progress = "Manchmal betrauere ich das Verlorene. Und dann erinnere ich mich daran, was es noch zu tun gibt.", completion = "Die Drust haben mehr Anima gestohlen, als ich erwartet hatte. Kaum zu glauben, dass sie uns mitten in einer Dürre so viel vorenthalten haben...\n\nWir müssen uns zurückholen, was wir können. Nicht nur um des Wildsamens willen, sondern auch, um die Pläne der Drust zu vereiteln.", sourceObjectiveStatus = "unverified-source-field" }
quests[58481] = { id = 58481, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blutrituale", description = "Anji und ich haben viele Kämpfe bestritten, also wissen wir mit ein paar Mogu umzugehen, aber die Blutmagie, die diese Dokani anwenden, ist einfach nur verstörend!\n\nAls ob es nicht schlimm genug wäre, dass sie jeden töten, der ihren Weg kreuzt, aber dann auch noch die Leichen für ihre unheiligen Rituale zu missbrauchen? Das ist unerträglich!\n\nTut mir einen Gefallen. Wenn ihr jemals eines dieser Rituale seht, haltet es auf! Nicht einmal unsere Feinde verdienen, durch diese dunkle Magie entehrt zu werden.", sourceObjective = "Vernichtet 6 Blutbrunnen im Tal der Ewigen Blüten.", completion = "Ich bin wirklich erleichtert, zu wissen, dass Ihr diesen Ritualen ein Ende bereitet habt.\n\nMir dreht sich der Magen um, wenn ich nur an sie denke.", sourceObjectiveStatus = "unverified-source-field" }
quests[58483] = { id = 58483, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Andenken", description = "Ich habe im Herzholzhain Geschichten vom Fall von Tirna Noch gehört. Ich hätte nie gedacht, dass ich es mit eigenen Augen sehen würde.\n\nDas macht mich sehr traurig. Und ich frage mich... ob dieses Schicksal auch meinen alten Hain erwartet.\n\nIch kann nicht glauben, dass alles, was hier einst existierte, wirklich verloren sein soll.\n\nVielleicht gibt es immer noch ein paar Erinnerungsstücke, die geborgen werden können. Etwas, um sich an die Gefallenen zu erinnern.", sourceObjective = "Sammelt gestohlene Andenken von getöteten Gegnern in Tirna Noch.", progress = "Ist das, was auch dem Herzholzhain droht? Und meiner alten Heimat?", completion = "Habt Dank.\n\nEs sind nur Dinge, aber sie bedeuten uns sehr viel. Manchmal ist es tröstlich, einfach nur ein Stück Vergangenheit in der Hand zu halten.\n\nDas bedeutet, dass nicht alles verloren ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[58484] = { id = 58484, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nehmt, was Ihr könnt", description = "Wir wissen, dass diese Eindringlinge die Überreste des Hains übernommen haben.\n\nAber warum? Warum sammeln sie so viel Anima und bringen sie an einen Ort?\n\nUnd wie sind sie in den Ardenwald gelangt?\n\nWir sollten wachsam bleiben und so viel Anima an uns bringen, wie wir nur finden können. Vielleicht kann all dieser Verlust doch noch zu etwas Gutem führen.", sourceObjective = "Nehmt geplünderte Anima aus Lagern in Tirna Noch an Euch.", progress = "Manchmal betrauere ich das Verlorene. Und dann erinnere ich mich daran, was es noch zu tun gibt.", completion = "Diese Anima wird Traumweber helfen, sein Ritual abzuschließen... und vielleicht auch die Geister retten, die ansonsten verloren wären.\n\nGute Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[58485] = { id = 58485, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erbaut für den Fall", description = "Die Baruk wenden die verbotene Kunst der Nekromantie an, um die Seelen gefallener Mogu in den Statuen einzufangen und sie dann für sich kämpfen zu lassen.\n\nDiese Praktiken sind eine Schande für unser Volk und dürfen nicht weiter angewandt werden.\n\nZertrümmert ihre geliebten Statuen und überlasst ihnen keine Gefäße, die sie mit ihren gestohlenen Geistern verseuchen können.", sourceObjective = "Vernichtet 6 Mogustatuen im Tal der Ewigen Blüten.", completion = "So, wie ihre Statuen zerfallen, wird es auch ihrem Klan ergehen.\n\nIhr habt eine angemessene Leistung gezeigt.", sourceObjectiveStatus = "unverified-source-field" }
quests[58486] = { id = 58486, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Drust zum Verlust", description = "Nur das Herz eines Hains kann die gewaltige Menge an Anima aufnehmen, die ich spüre.\n\nNachdem mein Hain geopfert wurde, wurde die Anima in seinem Herzen entnommen. Jetzt strotzt sein Herz wieder vor Anima.\n\nAnima, die aus anderen Hainen gestohlen wurde.\n\nWir müssen das Herz nicht nur für uns sichern, sondern für den ganzen Wald.\n\nIch vermute, sie werden uns nicht einfach dort hineinschlendern lassen. Macht Euch auf alles gefasst.", sourceObjective = "Tötet Vroth, Bollwerk von Thros, und macht Euch auf den Weg zum Herz des gefallenen Baums.", completion = "Wir haben es zum Herz geschafft. Gut gemacht.\n\nWenn das die wahre Natur aller Drust ist, ist der Ardenwald wirklich in einer verzweifelten Lage.", sourceObjectiveStatus = "unverified-source-field" }
quests[58487] = { id = 58487, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Plünderer ausplündern", description = "Unsere Überfälle auf Lei Shens Schatzkammern haben viel zum Untergang des Donnerkönigs beigetragen. Ich glaube, wir sollten hier dieselbe Strategie anwenden.\n\nSucht die Beute, die die Moguklans gehortet haben, und nehmt sie ihnen ab.\n\nWir müssen tun, was wir können, um ihr Vorrücken zu stören.", sourceObjective = "Plündert 3 mal Mogubeute im Tal der Ewigen Blüten.", completion = "Gut gemacht. Wir sollten diese Vorräte auch weiterhin unseren Gegnern vorenthalten.\n\nAuch die kleinsten Maßnahmen, um unsere Gegner zu stören, können das Blatt zu unseren Gunsten wenden.", sourceObjectiveStatus = "unverified-source-field" }
quests[58488] = { id = 58488, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herzschmerz", description = "Ich hatte recht! Ein großer Teil der Anima wurde im Herzen des Hains gelagert.\n\nDie Drust müssen sie im ganzen Ardenwald gesammelt haben.\n\nUnd jetzt holen wir sie uns zurück.\n\nSchnell, zerstört diese Barriere und schnappt Euch das Herz. Niya und ich werden Euch schützen.", sourceObjective = "Zerstört die Barriere und nehmt das Herz von Tirna Noch.", progress = "Wir werden diese Anima zurückgewinnen. Die Drust werden sie nicht für ihre Zwecke nutzen.", completion = "Jetzt haben wir das Herz und müssen nur noch einen Weg nach draußen finden.\n\nUnd es klingt, als würden sich Feinde nähern...", sourceObjectiveStatus = "unverified-source-field" }
quests[58490] = { id = 58490, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tödliche Erinnerung", description = "Unsere Verteidigung ist dürftig, dennoch zögert der Gegner, uns anzugreifen.\n\nSolange sie uns fürchten, werden sie nicht versuchen, unsere Verteidigung anzufechten.\n\nHaltet den Druck auf den Feind aufrecht. Greift ihre Stellungen entlang unseren Linien an.", sourceObjective = "Schaltet gegnerische Streitkräfte und Stellungen aus.", sourceObjectiveStatus = "unverified-source-field" }
quests[58496] = { id = 58496, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein unangenehmer Berater", description = "<Der Umschlag enthält eine Nachricht von König Anduin Wrynn.>\n\n{name},\n\nobwohl die Streitkräfte der Horde und der Allianz zusammenarbeiten, haben wir immer noch keine Spur der Armeen von N'Zoth finden können. Seit seiner Befreiung hat uns der Alte Gott um jeden Preis gemieden.\n\nNur das Licht weiß, was er für furchtbare Pläne für Azeroth hat.\n\nTrefft mich in Burg Sturmwind. Wir müssen einen Plan schmieden, wie wir N'Zoths Ränke aufdecken können, bevor es zu spät ist!\n\nMöge das Licht Euch beflügeln,\nKönig Anduin Wrynn", sourceObjective = "Sprecht mit König Anduin Wrynn in Burg Sturmwind.", progress = "Was wollt Ihr?", completion = "Anscheinend hat sich N'Zoths Verderbnis bereits in unseren Geist eingeschlichen. Wir haben keine Zeit zu verlieren.\n\nGeht mit Magni und Furorion und seht, was Ihr entdecken könnt. Ich stelle sicher, dass sich unsere Truppen jederzeit gegen einen Angriff zur Wehr zu setzen können.\n\nViel Glück.", sourceObjectiveStatus = "unverified-source-field" }
quests[58498] = { id = 58498, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Rückkehr des Kriegerkönigs", description = "Champion, Ihr habt Azeroth einen großen Dienst erwiesen, ich muss leider aber noch einen weiteren Gefallen von Euch erbitten. N'Zoth ist entfesselt, und wir wissen nicht, wann oder wo er zuschlagen wird.\n\nDieser Schlacht könnt Ihr Euch nicht allein stellen. Wenn die Zeit gekommen ist, wird mein Hammer an Eurer Seite sein!\n\nAllerdings müssen wir ihn zuerst holen.", sourceObjective = "Geht mit Magni und holt Furchtbrecher in Burg Sturmwind.", progress = "Braucht Ihr etwas, Champion?", completion = "Es wird guttun, endlich wieder in Aktion zu sein.\n\nLegen wir los!", sourceObjectiveStatus = "unverified-source-field" }
quests[58502] = { id = 58502, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herzensangelegenheit", description = "Es wird Zeit, dass wir Furorions Pläne umsetzen.\n\nEr wird in die Herzkammer zurückeilen. Wir sollten ihn dort treffen.", sourceObjective = "Kehrt zur Herzkammer zurück.", completion = "Gut, alle sind hier.\n\nLasst uns anfangen!", sourceObjectiveStatus = "unverified-source-field" }
quests[58504] = { id = 58504, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anklageschrift", description = "Wir haben Berichte aus Revendreth erhalten. Anscheinend hat man Maldraxxiverräter gefunden, die in ihrem Reich herumschleichen.\n\nEin Abgesandter aus Sündensturz möchte sich über die Animareserven unterhalten, die wir entdeckt haben.\n\nKommt mit mir. Wir brechen sofort auf.", sourceObjective = "Sucht die Anklägerin in den Hallen der Sühne in Revendreth auf.", completion = "Die Freude ist ganz meinerseits.", sourceObjectiveStatus = "unverified-source-field" }
quests[58505] = { id = 58505, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geplanter Untergang", description = "Unsere Verteidigung ist dürftig, dennoch zögert der Gegner, uns anzugreifen.\n\nSolange sie uns fürchten, werden sie nicht versuchen, unsere Verteidigung anzufechten.\n\nHaltet den Druck auf den Feind aufrecht. Greift ihre Stellungen entlang unseren Linien an.", sourceObjective = "Schaltet gegnerische Streitkräfte und Stellungen aus.", sourceObjectiveStatus = "unverified-source-field" }
quests[58506] = { id = 58506, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Netzwerkdiagnose", description = "Wir haben leider keine Ahnung, wo N'Zoth seit seiner Flucht lauert. Allerdings können wir uns denken, wo er vielleicht zuschlagen wird.\n\nAls die Hüter damals die Alten Götter einsperrten, haben sie Verteidigungsmechanismen gegen die Verderbnis in die Titanenschmieden eingebaut. Wenn N'Zoth Azeroth verderben will, muss er sie zuerst ausschalten.\n\nZum Glück haben wir eine Verbindung zu ihnen hergestellt, sodass wir sie von hier aus überwachen können. Seht es Euch einfach mal an.", sourceObjective = "Aktiviert die Titanenschalttafeln in der Herzkammer und überprüft den Status der Titanenschmieden in ganz Azeroth.", progress = "Die Konsolen sollten Euch verraten, wie es um die Schmieden bestellt ist.", completion = "Ich hatte gehofft, dass wir mehr Zeit für die Vorbereitung haben würden.\n\nJetzt scheint der beste Zeitpunkt zu sein, um zu handeln.", sourceObjectiveStatus = "unverified-source-field" }
quests[58515] = { id = 58515, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf der Suche nach Schriftrollen", description = "Die Kyrianer sind für ihre Sammlung an Schriftrollen und Schriften berühmt. Ich bin besonders an ihren Schriften über die interessiert, die sich ihren Reihen angeschlossen haben.\n\nWarum werden einige der besten Kämpfer in die Bastion geschickt, und nicht nach Maldraxxus?\n\nVielleicht bringt uns Nachforschung die Antwort.", sourceObjective = "Sammelt Informationen über die Kyrianer aus dem Tempel der Demut.", progress = "Mal sehen, wo ist dieses Papier hin?", completion = "Das wird sehr hilfreich sein. Es ist eine Schande, dass so viele Leute ihr Wissen nicht teilen möchten. Es ist töricht, es für sich zu behalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[58518] = { id = 58518, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Belastende Unterlagen", description = "Ich habe bemerkt, dass Ihr überrascht wart, diese seltsamen Waffen hier zu finden.\n\nAuch ich spüre die Essenz ihrer Macht. Sie ist seltsam vertraut...\n\nWir müssen herausfinden, wo die Waffen herkommen und wer sie mit derartiger Macht versehen hat.\n\n<Kael'thas lächelt.>\n\nWenn wir zwei der Anklägerin gemeinsam die Beweise präsentieren, erlaubt sie uns vielleicht, jene zu jagen, die hinter all dem stecken!", sourceObjective = "Entdeckt Beweise dafür, wer die Venthyr mit maldraxxischen Waffen versorgt.", progress = "Habt Ihr etwas gefunden?", completion = "Ein Lich?! Der Zehntherr arbeitet mit einem Lich aus Maldraxxus zusammen?!\n\nInwiefern? Zu welchem Zweck?\n\n<Die Anklägerin sammelt sich wieder.>\n\nVersteht Ihr, wie besorgniserregend das ist, {name}?\n\nSo etwas ist noch nie geschehen. So etwas sollte überhaupt nicht geschehen.\n\nPrinz Renathal wird wissen, was zu tun ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[58523] = { id = 58523, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ihr seid tot für mich", description = "Ich erwarte, dass Ihr kooperiert, will aber auch Resultate.\n\nUnsere Aufklärer haben ein Maldraxxilager im Endmorast entdeckt. Wir mutmaßen, dass Eure Art es benutzt hat, um die Animavorräte des Meisters zu entziehen.\n\nIch habe eine Kutsche gerufen, die uns dorthin bringt. Beeilen wir uns.", sourceObjective = "Folgt der Anklägerin zum Maldraxxilager.", completion = "Wir sind angekommen. Keine Zeit für Trödelei.", sourceObjectiveStatus = "unverified-source-field" }
quests[58524] = { id = 58524, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Es regnet Glitzer", description = "Ihr habt das Herz des Hains gefunden! Und es ist voller Anima!\n\nDie Drust sind nicht unbedingt begeistert, dass Ihr sie genommen habt. Sie versammeln sich überall im Wald in großen Massen!\n\nWir müssen Euch und die anderen sicher hier herausbringen.\n\nIch kann helfen. Habt Ihr Lust, ein wenig Glitzerchaos anzurichten?", sourceObjective = "Sprecht mit Lady Mondbeere und entkommt aus Tirna Noch.", completion = "Ihr habt ihre Anima mitten im Herzen des Hains gefunden und sie an Euch genommen? Beeindruckend.\n\nTraumweber wird höchst zufrieden sein. Aber ich denke, dass wir in Kürze erbosten Besuch erhalten werden.\n\nWir müssen schnell handeln, um dem Geist in diesem Wildsamen zu helfen... bevor wir überrannt werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[58525] = { id = 58525, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die zwei Seiten der Geschichte", description = "Ihr Sterblichen sagt immer \"Die Sieger schreiben Geschichte\", aber dies trifft in den Schattenlanden nicht zu.\n\nJeder hat seine eigene Version der Ereignisse. Ich möchte sie alle hören.\n\nEs gab da eine Autorin von Geschichtsbüchern, die sich im Sinistren Turm in Revendreth niederließ. Sie schrieb aus der Venthyrperspektive über diverse Übergriffe und Kämpfe an der Seite des Primus.\n\nWenn wir Exemplare ihrer Arbeiten finden könnten...", sourceObjective = "Findet Exemplare von \"Über Bein und Stein\" und \"Die Boshaftigkeit von Maldraxxus\".", completion = "Ihr habt sie gefunden! Was für ein wunderbarer Einblick in die Gedankengänge der Venthyr.", sourceObjectiveStatus = "unverified-source-field" }
quests[58530] = { id = 58530, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Versteckter Spiegel", description = "Wenn Renathal die Medaillons der Ernter einsetzen will, braucht er ein Medium, um ihre Macht zu konzentrieren. Denathrius' Verderbnis verseucht die Schmieden von Revendreth. Unsere Chancen stehen in der Bastion am besten.\n\nDie Bastion wird uns als Bewohner von Revendreth den Eintritt durch Oribos nicht gestatten.\n\nIhr müsst für uns einen Spiegel aktivieren, der dort vor langer Zeit verborgen wurde. Nehmt dies.\n\nWir haben ihn an einem selten genutzten Ort, in der Verhüllten Enklave, versteckt. Dort sollte niemand sein, vor allem nicht bei der Dürre.", sourceObjective = "Benutzt Laurents kompakten Handspiegel, um den versteckten Spiegel in der Bastion aufzudecken.", completion = "Es ist eine Weile her, dass ich auf diesen Ebenen war.\n\nIch bin überrascht, dass die Illusion so lange gehalten hat. Der Spiegel wurde vor vielen Jahren für Operationen im Namen des Meisters versteckt.\n\nAber das spielt jetzt keine Rolle. Wir müssen uns beeilen und sind nicht nur zum Beobachten hier.", sourceObjectiveStatus = "unverified-source-field" }
quests[58555] = { id = 58555, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein unentspanntes Wiedersehen", description = "Wir suchen den Obersten Schmied Mikanikos.\n\nNur er kann das Gerät herstellen, das wir brauchen. Ich habe schon einige seiner Kreationen gesehen. Wirklich beeindruckende Konstrukte und Waffen, die fast so stark sind wie die Mächtigsten von uns Steingeborenen.\n\nZuletzt habe ich ihn in seiner Werkstatt gesehen. Ein Ort voller Wunder, der als die Ewige Schmiede bekannt ist.\n\nWir treffen Euch dort. Es könnte zu viel Aufmerksamkeit erregen, als Gruppe zu reisen.", sourceObjective = "Trefft General Draven und Theotar an der Ewigen Schmiede.", completion = "Überlasst mir das Reden. Ein falsches Wort, und sie könnten das gesamte Abkommen kippen.\n\nJetzt ist wirklich nicht der Zeitpunkt für weiteres Blutvergießen zwischen den Reichen.", sourceObjectiveStatus = "unverified-source-field" }
quests[58557] = { id = 58557, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unterstützung aus Sündensturz", description = "Für den Sieg über die Verschmähten braucht das Emblem ein Artefakt der Buße, etwas, das dafür steht, für die Fehler der Vergangenheit Abbitte zu leisten und einen neuen Weg einzuschlagen.\n\nMir schwebt da ein bestimmtes Artefakt vor.\n\nVor langer Zeit sind hier in der Bastion viele Seelen aus Revendreth eingetroffen. Es waren reinere Seelen, als wir sie je aus Revendreth erhalten hatten.\n\nSie trugen das Zeichen des Siegels der Reue, einen Fokus, der den Prozess ihrer Läuterung beschleunigt hat.\n\nGeht nach Revendreth und findet dieses Siegel, damit wir seine Macht für unsere Zwecke nutzen können.", sourceObjective = "Trefft Euch mit der Kuratorin in Dunkelhafen in Revendreth.", completion = "Es tut mir leid, dass ich Euch nicht noch mehr sagen kann... Der Schlund hat meine Gedanken ziemlich verwirrt.\n\nIch werde Euch helfen, so gut ich kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[58558] = { id = 58558, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flug und Fluss von Informationen", description = "Die Gräfin weiß alles über die Lebensumstände jedes einzelnen Adligen in Revendreth. Dadurch stellt sie sicher, dass diese beständig in ihrer Schuld stehen.\n\nAber auch sie hat ein dunkles Geheimnis. Sie mag es vielleicht leugnen, aber auch sie war einst... eine Sterbliche.\n\nWir müssen herausfinden, wo sie ihren Sündenstein verwahrt. Das ist natürlich keine leichte Aufgabe.\n\nWir benötigen dafür ein paar Geheiminformationen. Die Venthyr im Kelchdistrikt tauschen ständig Gerüchte aus. Sammelt Briefe von ihren Kurieren, bis Ihr etwas von Interesse gefunden habt.", sourceObjective = "Sammelt Gerüchte der Gunst von den Kelchkurieren im Kelchdistrikt.", completion = "Drei Häuser, die in der Gunst der Gräfin stehen... Seltsam.\n\nKlingt, als werdet Ihr den Redelavdistrikt erkunden müssen!", sourceObjectiveStatus = "unverified-source-field" }
quests[58559] = { id = 58559, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Augen des Meisters", description = "Ich mache mir Sorgen wegen unseres Aufenthalts in der Stadt. Ihr habt sicher auch bemerkt, wie sehr wir hier... auffallen.\n\nDenathrius' Getreue haben ihre Augen überall, und man findet keine pflichtbewussteren Soldaten als die Steingeborenen.\n\nSie überwachen den Kelchdistrikt mit Augen und Ohren. Schaltet ihre Anführer aus, damit niemand unsere Anwesenheit verrät, bevor wir uns das Siegel besorgen konnten.", sourceObjective = "Tötet Evaala die Allsehende, Wächter Mastrus und Keraal den Reißer im Kelchdistrikt.", completion = "In dieser Stadt läuft es mir kalt den Rücken hinunter. Ich habe ständig das Gefühl, jemand würde mich beobachten und dass die Leute hinter meinem Rücken flüstern.\n\nDurch das Ausschalten der Anführer der Steingeborenen sollten die Informationen, die an Denathrius' Getreue gehen, etwas spärlicher ausfallen.", sourceObjectiveStatus = "unverified-source-field" }
quests[58560] = { id = 58560, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gotische Mode", description = "Ungesehen in die Stadt zu gelangen, war nicht so einfach, wie ich gedacht hatte.\n\nAls ich so durch den Matsch stapfte, bin ich diesen... kleinen Männern begegnet.\n\nVielleicht hat Kleia recht. Ich errege hier viel zu viel Aufmerksamkeit, um von Nutzen zu sein.\n\nAber vielleicht könnte ich mich verkleiden? Bitte helft mir, ein wenig Venthyrkleidung als Tarnung zu beschaffen.", sourceObjective = "Sammelt 5 Venthyrkleidungsstücke von Kelchbewohnern und aus Kleiderkoffern im Kelchdistrikt.", completion = "<Pelagos durchstöbert die Kleidung, die Ihr ihm gebracht habt.>\n\nSo ein schöner Stoff... Ich glaube, das könnte funktionieren!", sourceObjectiveStatus = "unverified-source-field" }
quests[58561] = { id = 58561, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Splitter der Gräfin", description = "Die Venthyr legen lange Wegstrecken durch verzauberte Spiegel zurück. Die Schlüssel, nach denen wir suchen, sind nicht wie jene in der Bastion, sondern Scherben eines Spiegels, der zum Standort des Sündensteins führt.\n\nNach den Informationen, die Ihr gefunden habt, wissen wir jetzt, welche drei Häuser im Besitz dieser Scherben sind.\n\nPrimula, Dunkelader und Sündzahn.\n\nGeht zu ihren Anwesen und holt die Scherben. Wir werden nach einem Rahmen suchen, in dem wir sie zusammensetzen können.", sourceObjective = "Sammelt die 3 Splitter der Gräfin.", completion = "Ich wette, Ihr habt die Adligen ganz schön in Aufruhr gebracht. Wir müssen uns beeilen.", sourceObjectiveStatus = "unverified-source-field" }
quests[58562] = { id = 58562, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Staubfänger", description = "So, wie ich die Gräfin kenne, und ich kenne sie gut, verfügt ihr Sündenstein über einen stärkeren Schutz als normale Schlüssel.\n\nSie hat eine Vorliebe dafür, ihre Tore mit Flüchen zu schützen. Ich kann ein Mittel herstellen, das uns schützt, aber dafür benötige ich die Blütenblätter einer bestimmten Blume, die man in den Redelavgärten findet.\n\nSammelt die Blütenblätter dieser Blume ein, damit ich uns vor den kommenden Gefahren schützen kann.", sourceObjective = "Sammelt 30 Todeslotusblütenblätter von Todeslotus im Redelavdistrikt.", progress = "Ich benötige viele Blütenblätter, um uns vier zu schützen.", completion = "<Die Kuratorin untersucht die Blütenblätter>\n\nEs ist vielleicht etwas wenig, aber ich glaube, das könnte funktionieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[58563] = { id = 58563, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tief ins Glas", description = "Der Spiegelrahmen befindet sich im unteren Bereich der Redelavhalle. Kleia und Pelagos warten dort.\n\nMithilfe dieser Scherben kann ich ihn zusammensetzen.\n\nWir gehen rein, schnappen uns den Sündenstein und konfrontieren die Gräfin. Nichts darf uns aufhalten.", sourceObjective = "Geht durch den Spiegel und holt den Sündenstein der Gräfin.", progress = "Die Venthyr schleppen ihre Vergangenheit wie eine Bürde mit sich herum, die schwer auf ihnen lastet.\n\nWir Kyrianer befreien sich von ihr.", completion = "So viel Macht in nur einem Stein.\n\nEure Vergangenheit kann gegen Euch eingesetzt werden. Darum befreien wir uns davon.", sourceObjectiveStatus = "unverified-source-field" }
quests[58564] = { id = 58564, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sünden der Vergangenheit", description = "Der Ruf der Gräfin gründet sich darauf, dass sie eine gebürtige Venthyr ist und niemals eine Seele war.\n\nDer Welt ihren Sündenstein zu offenbaren, käme für sie einer Katastrophe gleich. Das ist unser Druckmittel, um die gesuchte Information zu erhalten.\n\nSie wird uns sagen, wo Alwin ist. Wo das Siegel ist.\n\nDieser Spiegel führt in ihr Anwesen. Ich folge Euch als Verstärkung, aber der Kyrianer soll hier warten.\n\nLasst Euch nicht von ihr einschüchtern. Ihr habt hier die Macht.", sourceObjective = "Geht durch den Spiegel und sprecht mit der Gräfin.", progress = "Euer Glück, dass Euch die Kuratorin begleitet, Schlundgänger.\n\nHättet Ihr das hier allein riskiert, würdet Ihr Eure geliebte Bastion nie wiedersehen.", completion = "Ich werde Euch alles über das Siegel der Reue erzählen.\n\nUnd dann verschwindet Ihr. Sofort.", sourceObjectiveStatus = "unverified-source-field" }
quests[58565] = { id = 58565, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Land des Lichts", description = "Im Glutdistrikt leben alle, die von der Gesellschaft in Revendreth ausgestoßen wurden. Es spielt keine Rolle, ob sie offen rebelliert haben, einem Adeligen in die Quere gekommen sind oder Denathrius einfach nur falsch angesehen haben.\n\nEs ist ein vom Licht versengtes Land, das die Venthyr in den Wahnsinn treibt, wenn sie es nicht schaffen, im Schatten zu bleiben.\n\nWenn Alwin dort ist, kommt vielleicht jede Hilfe zu spät.\n\nGehen wir zu Theotar beim Refugium des Wahnsinnigen. Er freut sich bestimmt, Euch zu sehen.", sourceObjective = "Trefft Euch mit Theotar beim Refugium des Wahnsinnigen im Glutdistrikt.", completion = "Ah, {name}, willkommen zurück in Revendreth!\n\nErlaubt mir, Euch jemanden vorzustellen, der gute Dienste leisten könnte.", sourceObjectiveStatus = "unverified-source-field" }
quests[58566] = { id = 58566, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taten sagen mehr als Worte", description = "<Der Ascheghul betrachtet Euch und überprüft dabei besonders Eure Waffen und Rüstung.\n\nDann wandert sein Blick zu Euren kyrianischen Begleitern und schließlich wieder zu Theotar, der ihm zunickt.\n\nAlwin gibt Euch mit einer Geste zu verstehen, dass Ihr ihm folgen sollt.>", sourceObjective = "Folgt dem hirnverbrannten Alwin durch den Aschegang.", completion = "<Alwin sieht Euch an, dann Kleia.\n\nEr nickt mit einem Ausdruck der Entschlossenheit in den Augen.>", sourceObjectiveStatus = "unverified-source-field" }
quests[58567] = { id = 58567, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Schutz der Dunkelheit", description = "Bis jetzt habe ich nur Erzählungen über den Glutdistrikt gehört.\n\nDer Anblick ist atemberaubend... aber auch furchtbar.\n\nDas Licht hier verbrennt die Venthyr. Es versengt ihr Fleisch und treibt sie in den Wahnsinn.\n\nNur in der Dunkelheit finden sie Schutz, aber ein paar Schläger haben außerhalb dieser Zuflucht alle geschützten Orte vereinnahmt.\n\nFür sie gibt es keine Erlösung. Nur Gerechtigkeit.", sourceObjective = "Tötet 8 ausgestoßene Venthyr im Aschegang.", completion = "Wer Opfer seiner Laster wird, muss zur Rechenschaft gezogen werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[58568] = { id = 58568, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gegeißelt vom Licht", description = "Auf dem Weg hierher haben wir viele Ascheghule gesehen, die laut vor Schmerz geschrien haben. Ihre Verbrennungen durch das Licht sind furchtbar.\n\nNachdem ich Alwin und die anderen hier getroffen habe, ist mein Herz schwer vor Mitgefühl.\n\nSie haben so viel von sich selbst verloren und müssen trotzdem jeden Tag deswegen auch noch leiden.\n\nSammelt bitte einige Beeren aus dem Aschegang. Ich glaube, ich könnte sie mit Anima erfüllen und daraus eine Heilsalbe für ihre Wunden herstellen.\n\nDas ist wohl das Mindeste, was ich tun kann.", sourceObjective = "Sammelt 25 Dickichtbeeren im Aschegang.", progress = "Die Einwohner des Glutdistrikts haben genug für ihre Fehler gelitten.\n\nDas Licht geht mit seiner Strafe zu weit.", completion = "Es ist meine Pflicht, allen zu helfen, die Schmerzen leiden. Diese Salbe soll helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[58569] = { id = 58569, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Torheit des Neides", description = "<Alwin zeigt auf einen Venthyr auf dem Sims über Euren Köpfen.\n\nDann stößt er ein leises und tiefes Knurren aus.>", sourceObjective = "Tötet Herzog Vielle und nehmt das Siegel der Reue an Euch.", progress = "Alwin hat uns weit gebracht. Wir müssen das Siegel holen!", completion = "Kann es wirklich wahr sein? Das Ziel unserer langen Suche...", sourceObjectiveStatus = "unverified-source-field" }
quests[58570] = { id = 58570, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Wort zum Abschied", description = "Wir müssen das Siegel zur Bastion bringen.\n\nAlwin hat seine Gerechtigkeit bekommen. Er hat das Siegel unserer Obhut anvertraut.\n\nWir sollten uns von allen im Refugium des Wahnsinnigen verabschieden und dann nach Hause gehen.\n\nIch freue mich schon auf den blauen Himmel und die weiten Felder der Bastion.", sourceObjective = "Sprecht mit der Kuratorin beim Refugium des Wahnsinnigen und kehrt dann in die Elysische Feste zurück.", progress = "Ihr seid zurück! Mit guten Nachrichten, wie ich hoffe?", completion = "Kalisthenes Bericht ist bedenklich... aber nicht mein Problem! Siegel sollte perfekt funktionieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[58571] = { id = 58571, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Siegel der Reue", description = "Die Vorbereitungen für das Siegel sind abgeschlossen.\n\nGeht und legt es in das Emblem ein. Seid behutsam, aber entschlossen! Bewegt Euch zielgerichtet, aber mit ruhiger Hand.", sourceObjective = "Platziert das Siegel der Reue im Emblem des Aufstiegs.", progress = "<Die Kugel hängt direkt vor Euch. Das Siegel in Eurer Hand pulsiert schnell.>", completion = "<Das Siegel der Reue blitzt förmlich vor Macht auf, als Ihre Eure Hand wegzieht.\n\nEin einzelnes Objekt, das die Bewohner der Bastion und von Revendreth auf mehr als nur die offensichtliche Art und Weise verbindet.>", sourceObjectiveStatus = "unverified-source-field" }
quests[58575] = { id = 58575, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Etwas für alle", description = "Viele Wettstreiter finden ihr Ende im Theater der Schmerzen. Aber ihre Waffen sind immer noch so gut wie neu!\n\nEs kann kostspielig werden, einen neuen Rekruten auszurüsten, besonders wenn man nicht sicher ist, dass er den ersten Kampf überleben wird. Deshalb statten wir sie mit \"leicht gebrauchten\" Waffen aus.\n\nSammelt sie für mich, ja? Eine gute Waffe darf nicht verschwendet werden!", sourceObjective = "Sammelt 12 Waffen der Gefallenen.", progress = "Die Waffen, die Ihr sammelt, könnten von einem zukünftigen Champion geschwungen werden!", completion = "Diese Waffen werden sinnvoll eingesetzt werden. Hoffentlich müssen wir nicht einige von ihnen erneut einsammeln.", sourceObjectiveStatus = "unverified-source-field" }
quests[58582] = { id = 58582, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr des Schwarzen Prinzen", description = "<Der Umschlag enthält eine Nachricht von Valeera Sanguinar.>\n\n{name},\n\nich bin gerade von einem Treffen mit König Wrynn in Sturmwind zurückgekehrt.\n\nWir haben viel zu besprechen.\n\nTrefft mich so bald wie möglich im Großen Siegel.\n\nAl diel shala,\nValeera", sourceObjective = "Sprecht mit Valeera Sanguinar im Großen Siegel in Dazar'alor.", progress = "Ja?", completion = "Ich hoffe, dass Furorions Wissen uns zum Alten Gott leiten kann.\n\nWir haben sonst kaum etwas in der Hand.", sourceObjectiveStatus = "unverified-source-field" }
quests[58583] = { id = 58583, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herzensangelegenheit", description = "Der Sprecher hat mich gebeten, Euch zu schicken, damit Ihr ihn und Furorion bei ihren Bemühungen unterstützt.\n\nIhr habt Euch als <wichtiger Verbündeter/wichtige Verbündete> Azeroths erwiesen, und ich vermute, dass Ihr in den bevorstehenden Schlachten eine große Rolle spielen werdet.\n\nHoffen wir, dass der Rest der Horde und der Allianz ihre Konflikte beilegen können, um es mit einem gemeinsamen Feind aufzunehmen.", sourceObjective = "Trefft Euch mit Magni Bronzebart in der Herzkammer.", completion = "Ah, Ihr seid da! Genau rechtzeitig!\n\nFurorion hat einen Plan, wie wir N'Zoth vielleicht überlisten können. Aber sobald der Alte Gott sein Gesicht zeigt, müsst Ihr ihm ordentlich eins auf selbiges geben!\n\nFangen wir an!", sourceObjectiveStatus = "unverified-source-field" }
quests[58584] = { id = 58584, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wiedergutmachung", description = "Generalin Kaal wurde vor langer Zeit wegen einer Mission für Denathrius hierhergeschickt.\n\nBei dieser Mission haben sie Animaschröpfer verborgen, was es unmöglich macht, ihre Anwesenheit zu entdecken. So wollten sie die Menge an Anima begrenzen, die dieser Werkstatt zur Verfügung steht. Dadurch wurde die ganze Region instabil. Die Verschmähten haben es wohl bemerkt und diese Schwäche ausgenutzt.\n\nDiese Taten von damals sind das genaue Gegenteil von unserem heutigen Ziel. Nehmt Theotar mit und zerstört diese Schröpfer.", sourceObjective = "Sprecht mit Theotar in der Ewigen Schmiede. Enttarnt und zerstört anschließend 5 versteckte Animaschröpfer.", completion = "Die Aufgabe ist erledigt.\n\nDas sollte die Rückkehr der Anima begünstigen.\n\nEure Hingabe an unsere Sache ist beachtlich. Ich kann mir niemanden vorstellen, der diesen Umhang mehr verdient.", sourceObjectiveStatus = "unverified-source-field" }
quests[58585] = { id = 58585, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keine Freundin von mir", description = "Werkzeug. Ohne mein Werkzeug kann ich nicht arbeiten!\n\nFamula, mein ehemaliger Lehrling, hat alles gestohlen, als sie zu den Verschmähten ging.\n\nEs bricht mir das Herz. Sie war so vielversprechend.\n\nIhr müsst sie aufhalten.", sourceObjective = "Tötet Famula in der Ewigen Schmiede und sammelt Mikanikos' Werkzeugkasten ein.", progress = "Ich brauche mein Werkzeug. Ohne kann ich meine Aufgabe auf keinen Fall erledigen.", completion = "Mein Werkzeug. Immerhin hat Famula sich gut darum gekümmert.", sourceObjectiveStatus = "unverified-source-field" }
quests[58586] = { id = 58586, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aus Alt macht Neu", description = "Wenn wir was bauen möchten, das auf Eurer Mission hilft, brauchen wir Metall.\n\nDie Konstrukte der Verschmähten haben Metallteile, die für unsere Zwecke brauchbar sind. Wurden aber durch die Verschmähten besudelt, also müssen wir noch etwas Arbeit investieren.\n\nSammelt ihr Metall und schmelzt es in den Flammen der Ewigen Schmiede ein. So läutern wir die Verderbnis.", sourceObjective = "Vernichtet Konstrukte der Verschmähten, sammelt 5 besudelte Zenturiokomponenten und schmelzt sie ein.", progress = "Habt Ihr das Metall?", completion = "Metall sollte reichen. Gute Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[58589] = { id = 58589, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rastlose Träumerin", description = "Wir haben die benötigte Anima und müssen nun das Herz von Tirna Noch auf die Schreine des Winterschlafbeckens einstimmen.\n\nDann können wir die Alpträume des Wildsamens zutage fördern und sie auflösen.\n\nBringt das Herz zu den Schreinen außerhalb des Winterschlafbeckens im Traumschreinbecken. Dann bringt das Herz zurück zu dem Wildsamen, um die Vorbereitungen für das Ritual abzuschließen.\n\nAber seid auf der Hut. Diener der Drust scheinen sich in der Nähe des Hains zu versammeln.", sourceObjective = "Stimmt das erfüllte Herz des Baums an den Schreinen im Traumschreinbecken ein.", progress = "Der Geist träumt.", completion = "Ihr seid ein Naturtalent. Jetzt können wir die Alpträume des Geistes offenlegen und uns direkt um sie kümmern.\n\nWenn es uns gelingt, wird sie viel mehr Ruhe finden.", sourceObjectiveStatus = "unverified-source-field" }
quests[58590] = { id = 58590, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Visionen der Träumerin: Ursprünge", description = "Der Geist im Wildsamen träumt von seiner Geburt und Jugend in den ersten Tagen seiner Welt.\n\nGeht zum ersten Traumschrein außerhalb des Winterschlafbeckens. Meditiert am Schrein im Becken und besänftigt die Vision vom Anfang seines Lebens.", sourceObjective = "Ringt mit der Vision des Geistes über seinen Ursprung.\n\nWenn Ihr die Vision verlasst, könnt Ihr mit dem Portal zur Vision der Träumerin im Traumschreinbecken interagieren, um erneut einzutreten.", completion = "Wir alle beginnen irgendwo. Manchmal an unerwarteten Orten. Ich aber bin aus dem Boden geschossen wie eine Blume.", sourceObjectiveStatus = "unverified-source-field" }
